'This_Year' => 'यो वर्ष',
'Code_Invalid_CODE39' => 'CODE39 ले अंकहरू, ठूला अक्षरहरू र - . $ / + % स्पेस मात्र अनुमति दिन्छ',
'Code_Invalid_EAN13' => 'EAN13 का लागि 12 अंक (वा मान्य चेक अंकसहित 13) आवश्यक छ',
'Code_Invalid_EAN8' => 'EAN8 का लागि 7 अंक (वा मान्य चेक अंकसहित 8) आवश्यक छ',
'Code_Invalid_UPC' => 'UPC का लागि 11 अंक (वा मान्य चेक अंकसहित 12) आवश्यक छ',
'Online_Store_Accounts' => 'अनलाइन स्टोर खाताहरू',
'Customers_without_login_alert' => 'यी तपाईंका POS / वाक-इन ग्राहकहरू हुन् जसको अहिलेसम्म अनलाइन स्टोर खाता छैन। ग्राहकले तपाईंको अनलाइन स्टोरमा साइन इन गरी किनमेल गर्न सकून् भनी स्टोर लगइन (इमेल + पासवर्ड) सिर्जना गर्न "खाता दर्ता गर्नुहोस्" प्रयोग गर्नुहोस्।',
'Customers_with_login_alert' => 'यी ग्राहकहरूको अनलाइन स्टोर खाता छ र उनीहरू तपाईंको स्टोरफ्रन्टमा साइन इन गर्न सक्छन्। यहाँ गरिएका परिवर्तनहरू (इमेल, पासवर्ड, स्थिति, ब्लक) ले उनीहरूको अनलाइन स्टोर लगइनलाई मात्र असर गर्छन् - POS ग्राहक रेकर्डलाई होइन।',
'Assigned_Permissions' => 'तोकिएका अनुमतिहरू',
'Modules' => 'मोड्युलहरू',
'Resize_Product_Images' => 'उत्पादन तस्बिरहरूको आकार परिवर्तन गर्नुहोस्',
'Resize_Product_Images_Help' => 'उत्पादन, भेरियन्ट र ग्यालेरी तस्बिरहरू सुरक्षित गर्दा तिनको आकार घटाउनुहोस्। अपलोड गरिएका फाइलहरू मूल रिजोल्युसनमै सुरक्षित गर्न यसलाई बन्द गर्नुहोस् (ठूला फाइलहरू, ढिला पृष्ठहरू)।',
'Product_Image_Max_Size' => 'उत्पादन तस्बिरको अधिकतम आकार',
'Product_Image_Max_Size_Help' => 'सुरक्षित गरिएका उत्पादन तस्बिरहरू मिलाइने सबैभन्दा लामो किनारा, पिक्सेलमा। आकार अनुपात कायम राखिन्छ र साना तस्बिरहरू कहिल्यै ठूला बनाइँदैनन्।',
'Grid_View' => 'कार्डहरू',
'Table_View' => 'तालिका',
'Image_Max_2MB' => 'तस्बिर 2 MB वा सोभन्दा सानो हुनुपर्छ।',
'Units_Guide_Title' => 'एकाइहरूले कसरी काम गर्छन्',
'Units_Guide_Base' => 'आधार एकाइ: "आधार एकाइ" खाली छोड्नुहोस्। स्टक सधैं यही एकाइमा गनिन्छ, उदाहरणका लागि थान।',
'Units_Guide_Sub' => 'उप-एकाइ: "आधार एकाइ" छान्नुहोस्, त्यसपछि यसलाई त्यो आधार एकाइमा रूपान्तरण गर्न "अपरेटर" र "अपरेसन मान" प्रयोग गर्नुहोस्।',
'Units_Guide_Example_Multiply' => 'उदाहरण: आधार एकाइ थान, अपरेटर * र मान 12 भएको बक्स। 1 बक्स बेच्दा स्टकबाट 12 थान घट्छ।',
'Units_Guide_Example_Divide' => 'उदाहरण: आधार एकाइ किलोग्राम, अपरेटर / र मान 1000 भएको ग्राम। 500 ग्राम बेच्दा स्टकबाट 0.5 किलोग्राम घट्छ।',
'Units_Guide_Note' => 'आधार एकाइहरू मात्र "आधार एकाइ" को रूपमा छान्न सकिन्छ, र उप-एकाइहरूले प्रयोग गरिरहेसम्म एकाइ मेटाउन सकिँदैन।',
'Amount_Paid' => 'भुक्तानी गरिएको रकम',
'Payment_Amounts_Help' => 'भुक्तानी गरिएको रकमले मौज्दात चुक्ता गर्छ र बाँकी घटाउँछ। प्राप्त रकम भनेको हस्तान्तरण गरिएको नगद हो: यो फिर्ता दिनुपर्ने रकम गणना गर्न मात्र प्रयोग हुन्छ, र बाँकीमा परिवर्तन गर्दैन।',
'Show_Tax_Desc' => 'चेकआउटमा सम्पूर्ण बिक्रीमा लागू गरिएको कर, कुल रकमहरूमा छुट्टै "अर्डर कर" लाइनको रूपमा प्रिन्ट गरिन्छ।',
'Show_Items_Tax_Desc' => 'प्रत्येक उत्पादनको आफ्नै करको योग, "कुल वस्तु कर" लाइनको रूपमा प्रिन्ट गरिन्छ। सक्षम गर्दा, उप-जम्मा यी करहरू बाहेक देखाइन्छ।',
'Show_Discount_Desc' => 'सम्पूर्ण बिक्रीमा लागू गरिएको छुट (कुनै पनि अंक छुटसहित), कुल रकमहरूमा छुट्टै लाइनको रूपमा प्रिन्ट गरिन्छ।',
'Show_Product_Discount_Desc' => 'प्रत्येक उत्पादनको आफ्नै छुट, वस्तु सूचीमा त्यो उत्पादनमुनि प्रिन्ट गरिन्छ।',
'Receipt_Font_Family' => 'रसिद फन्ट',
'Receipt_Font_Family_Desc' => 'प्रिन्ट गरिएको रसिदका सबै पाठका लागि प्रयोग हुने फन्ट। "पूर्वनिर्धारित" ले मानक रसिद फन्टहरू राख्छ।',
'Receipt_Font_Size' => 'रसिद फन्ट आकार (px)',
'Receipt_Font_Size_Desc' => 'सम्पूर्ण रसिदको पाठ आकार, 8 देखि 24 पिक्सेलसम्म। पूर्वनिर्धारित आकार राख्न खाली छोड्नुहोस्।',
'Font_Default' => 'पूर्वनिर्धारित',
'Amount_Paid_Help' => 'यो कागजातमा लागू गरिएको रकम; यसले बाँकी रकम घटाउँछ।',
'Received_Amount_Help' => 'वास्तवमा हस्तान्तरण गरिएको नगद। भुक्तानी गरिएको रकमभन्दा माथिको जुनसुकै रकम फिर्ताको रूपमा दिइन्छ र बाँकी घटाउँदैन।',
'OpeningBalanceReceived' => 'प्राप्त सुरुवाती मौज्दात',
'OpeningBalancePaid' => 'भुक्तानी गरिएको सुरुवाती मौज्दात',
'Customize_Profit' => 'नाफा अनुकूलन गर्नुहोस्',
'Custom_Profit' => 'अनुकूल नाफा',
'Custom_Profit_Hint' => 'आफ्नै नाफा आँकडा बनाउन कुन रकमहरू जोड्ने वा घटाउने छान्नुहोस्। तपाईंको छनोट यो उपकरणमा सुरक्षित हुन्छ।',
