'Discounts_Given' => 'दिइएको छुट (बिक्री)',
'Discounts_Received' => 'प्राप्त छुट (खरिद)',
'Shipping_Charged' => 'लिइएको ढुवानी शुल्क (बिक्री)',
'Shipping_Paid' => 'तिरिएको ढुवानी शुल्क (खरिद)',
'Expenses_By_Category' => 'श्रेणीअनुसार खर्चहरू',
'Daily_Trend' => 'दैनिक प्रवृत्ति',
'Additional_Information' => 'थप जानकारी',
'Warehouses_Tab_Help' => 'आफ्ना गोदामहरू (स्टोर/शाखाहरू) व्यवस्थापन गर्नुहोस्। प्रत्येक गोदामले आफ्नै स्टक राख्छ, र हरेक कागजात — बिक्री, खरिद, स्थानान्तरण, समायोजन — तीमध्ये कुनै एकमा रेकर्ड गरिन्छ।',
'Warehouse_Locations_Tab_Help' => 'प्रत्येक गोदामभित्र र्‍याक / सेल्फ स्थानहरू परिभाषित गर्नुहोस् (जस्तै गल्ली 2 – र्‍याक B)। वस्तुहरू भौतिक रूपमा कहाँ राखिएका छन् देखाउन तिनलाई उत्पादनहरूमा तोक्नुहोस्।',
'Already_Converted' => 'बिक्रीमा रूपान्तरण गरियो',
'Salesperson' => 'बिक्रेता',
'Select_Salesperson' => 'बिक्रेता छान्नुहोस्',
'You' => 'तपाईं',
'Enable_Pos_Salesperson_Switch' => 'चेकआउटको क्रममा बिक्रेता परिवर्तन गर्नुहोस्',
'Enable_Pos_Salesperson_Switch_Hint' => 'लगआउट नगरी बिक्रीलाई अर्को कर्मचारीको नाममा गन्न सकियोस् भनी POS स्क्रिनमा बिक्रेता छनोटकर्ता देखाउनुहोस्। छानिएको बिक्रेता बिलमा सुरक्षित हुन्छ र बिक्री रिपोर्टहरूमा प्रयोग गरिन्छ; सक्रिय POS सत्र परिवर्तन हुँदैन।',
'Wallet_Payment_Method_Missing' => 'Wallet भुक्तानी विधि छैन',
'Wallet_Payment_Method_Missing_Help' => 'ठ्याक्कै "Wallet" नाम भएको कुनै भुक्तानी विधि फेला परेन। POS वालेट भुक्तानी यही नामबाट मिलाइन्छ, त्यसैले तपाईंले यहाँ "Wallet" नामको भुक्तानी विधि नथपेसम्म ग्राहकहरूले आफ्नो वालेटबाट भुक्तानी गर्न सक्दैनन्:',
'Show_Previous_Dues_Line' => 'अघिल्ला बाँकीहरूको लाइन देखाउनुहोस्',
'Show_Previous_Dues_Line_Desc' => 'यो बिक्रीअघि ग्राहकले तिर्न बाँकी रकम। शून्यभन्दा बढी हुँदा मात्र प्रिन्ट गरिन्छ।',
'Show_Net_Balance_Line' => 'खुद मौज्दात लाइन देखाउनुहोस्',
'Show_Net_Balance_Line_Desc' => 'अघिल्ला बाँकीहरू र यो बिक्रीमा अझै तिर्न बाँकी रकम। अघिल्ला बाँकीहरू शून्यभन्दा बढी हुँदा मात्र प्रिन्ट गरिन्छ।',
'QZ_Tray_Printer' => 'QZ Tray (यो कम्प्युटरमा रहेको प्रिन्टर)',
'QZ_Printer_Name_Hint' => 'QZ Tray चलिरहेको कम्प्युटरमा देखिनेअनुसार प्रिन्टरको नाम। त्यो कम्प्युटरको पूर्वनिर्धारित प्रिन्टर प्रयोग गर्न खाली छोड्नुहोस्। प्रिन्टरहरू पत्ता लगाउन ⟳ मा क्लिक गर्नुहोस्।',
'QZ_Not_Running' => 'यो कम्प्युटरमा QZ Tray चलिरहेको छैन। यसलाई qz.io बाट स्थापना गरी चलिरहन दिनुहोस्, त्यसपछि QZ ले सोध्दा यो वेबसाइटलाई अनुमति दिनुहोस्।',
'Detect_Printers' => 'प्रिन्टरहरू पत्ता लगाउनुहोस्',
'QZ_Download_Cert' => 'प्रमाणपत्र डाउनलोड गर्नुहोस् (override.crt)',
'QZ_Setup_Title' => 'QZ Tray प्रिन्टिङ कसरी सेटअप गर्ने (लेबल प्रिन्ट गर्ने प्रत्येक कम्प्युटरमा एक पटक)',
'QZ_Step_Install' => '1. यो कम्प्युटरमा QZ Tray स्थापना गर्नुहोस् — qz.io बाट निःशुल्क डाउनलोड गर्नुहोस्, त्यसपछि सुरु गरी चलिरहन दिनुहोस् (यो Windows मा system tray मा वा macOS मा menu bar मा रहन्छ)।',
'QZ_Step_Connect' => '2. आफ्नो लेबल प्रिन्टर USB बाट जोड्नुहोस् र यो अपरेटिङ सिस्टममा स्थापित छ कि छैन जाँच गर्नुहोस् (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners)।',
'QZ_Step_Detect' => '3. यो कम्प्युटरका प्रिन्टरहरू पत्ता लगाउन माथि "प्रिन्टरको नाम" छेउको ⟳ बटनमा क्लिक गर्नुहोस्, त्यसपछि आफ्नो लेबल प्रिन्टर छान्नुहोस्। कम्प्युटरको पूर्वनिर्धारित प्रिन्टर प्रयोग गर्न फिल्ड खाली छोड्नुहोस्।',
'QZ_Step_Cert' => '4. अनुमति पपअपबिना प्रिन्ट गर्न, तलको प्रमाणपत्र डाउनलोड गरी override.crt नाममा परिवर्तन गरेर QZ Tray स्थापना फोल्डरमा प्रतिलिपि गर्नुहोस् (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray)। त्यसपछि QZ Tray बन्द गरी फेरि सुरु गर्नुहोस्।',
'QZ_Step_Test' => '5. तल "परीक्षण लेबल प्रिन्ट गर्नुहोस्" मा क्लिक गर्नुहोस्। QZ Tray ले अनुमति मागेमा Allow मा क्लिक गर्नुहोस् — प्रमाणपत्र स्थापना भएपछि यसले फेरि सोध्दैन।',
'QZ_Step_Save' => '6. यी सेटिङहरू सुरक्षित गर्न पेश गर्नुहोस् मा क्लिक गर्नुहोस्। बारकोड प्रिन्ट पृष्ठका लेबलहरू अब ब्राउजर प्रिन्ट संवादबिना सिधै यो प्रिन्टरमा प्रिन्ट हुनेछन्।',
'QZ_Setup_Note' => 'QZ Tray तपाईंले ब्राउज गरिरहेको कम्प्युटरमा चल्छ, त्यसैले Stocky रिमोट सर्भरमा होस्ट गरिएको हुँदा पनि यो काम गर्छ। लेबल प्रिन्ट गर्ने हरेक कम्प्युटरमा QZ Tray स्थापना हुनुपर्छ।',
'PWA_Enabled' => 'स्थापना गर्न मिल्ने एप सक्षम गर्नुहोस्',
'PWA_Enabled_Help' => 'ब्राउजरहरूलाई यो एप फोन, ट्याब्लेट र डेस्कटपमा स्थापना गर्ने प्रस्ताव गर्न दिन्छ, र अफलाइन पृष्ठहरू क्यासमा राखिरहन्छ। यसलाई बन्द गर्दा सबैतिरबाट स्थापना प्रम्प्ट हट्छ र अर्को भ्रमणमा क्यास खाली हुन्छ।',
'PWA_Identity' => 'एप पहिचान',
'PWA_Launch' => 'सुरुवात र देखावट',
'PWA_App_Name' => 'एपको नाम',
'PWA_App_Name_Help' => 'स्थापना प्रम्प्ट र एप सूचीमा देखाइन्छ। रूपरङ सेटिङहरूको एप नाम प्रयोग गर्न खाली छोड्नुहोस्।',
'PWA_Short_Name' => 'छोटो नाम',
