'Label_Render_Mode' => 'लेबल रेन्डरिङ',
'Label_Render_Mode_Hint' => 'लेबल कसरी बनाइन्छ। प्रिन्टर फन्ट सबैभन्दा छिटो छ र सबैभन्दा स्पष्ट बारकोड दिन्छ, तर प्रिन्टरको आफ्नै टाइपफेसमा आधारभूत ल्याटिन अक्षरहरू मात्र प्रिन्ट गर्छ। पूर्वावलोकन तस्बिरले तपाईंको लेबल डिजाइन ठ्याक्कै उस्तै बनाउँछ — तपाईंले छानेको फन्ट, कुनै पनि भाषा — समर्पित लेबल सफ्टवेयरले जस्तै।',
