'Calibration_Sent' => 'क्यालिब्रेसन सुरु भयो — प्रिन्टरले मापन गर्न केही खाली लेबलहरू अगाडि बढाउनेछ। रोकिएपछि परीक्षण प्रिन्ट चलाउनुहोस्।',
