'Label_Printer_Dpi_Hint' => 'अधिकांश लेबल प्रिन्टरहरू 203 dpi का हुन्छन्। निश्चित हुनुहुन्न? तलको "रिजोल्युसन पत्ता लगाउनुहोस्" बटन प्रयोग गर्नुहोस् — यसले उत्तर प्रिन्ट गर्छ।',
'Find_Resolution' => 'रिजोल्युसन पत्ता लगाउनुहोस्',
