'Dpi_Test_Sent' => '203 र 300 चिन्ह लगाइएका दुई लेबलहरू प्रिन्ट हुँदैछन्। सही लेबलले चारै तर्फ सानो, बराबर किनारासहित पूर्ण आयत देखाउँछ — "प्रिन्टहेड रिजोल्युसन" लाई त्यही नम्बरमा सेट गरी सुरक्षित गर्नुहोस्।',
'Label_Offset_X' => 'तेर्सो अफसेट (mm)',
