'Related_Products_Hint' => 'यो उत्पादन पृष्ठको "सम्बन्धित उत्पादनहरू" मा देखाइने उत्पादनहरू क्रमानुसार छान्नुहोस्। स्वचालित नियम (उही श्रेणी, त्यसपछि नयाँ) प्रयोग गर्न खाली छोड्नुहोस्।',
'Enable_Wholesale_Pricing' => 'परिमाणअनुसार थोक मूल्य',
'Enable_Wholesale_Pricing_Hint' => 'उत्पादनहरूमा परिमाण तहहरू (10-19 थान, 20-49 थान, 100+ ...) राख्न दिनुहोस् जसले अर्डर गरिएको परिमाण कुनै तहमा पुग्दा POS र अनलाइन स्टोरमा खुद्रा मूल्यलाई स्वतः प्रतिस्थापन गर्छन्। यसलाई बन्द गर्दा सबै कुरा फेरि सामान्य खुद्रा मूल्यमा बिक्री हुन्छ — कन्फिगर गरिएका तहहरू राखिन्छन्, केवल लागू हुँदैनन्।',
'Wholesale_Pricing_By_Quantity' => 'परिमाणअनुसार थोक मूल्य',
'Wholesale_Pricing_By_Quantity_Hint' => 'अर्डर गरिएको परिमाण कुनै तहमा पुगेपछि प्रति थान मूल्य। खुला अन्त्य भएको माथिल्लो तहका लागि अधिकतम खाली छोड्नुहोस् (जस्तै 100 र माथि)। पहिलो तहभन्दा तल उत्पादन सामान्य खुद्रा मूल्यमा बिक्री हुन्छ।',
'Wholesale_Pricing_Variants_Hint' => 'एउटै तह-सूचीले सम्पूर्ण उत्पादन समेट्छ: प्रत्येक भेरियन्टको आफ्नै लाइन कुनै तहमा पुगेपछि त्यो तहको मूल्यमा बिक्री हुन्छ।',
'Min_Quantity' => 'न्यूनतम परिमाण',
'Max_Quantity' => 'अधिकतम परिमाण',
'Price_Per_Piece' => 'प्रति थान मूल्य',
'Wholesale' => 'थोक',
'Wholesale_Tier_Applied' => 'यो लाइनमा थोक परिमाण तह लागू हुन्छ',
'Orders_Guide' => 'अर्डर गाइड',
'Ord_Guide_Intro' => 'तपाईंको अनलाइन स्टोरमा राखिएको अर्डर कसरी तपाईंको स्टक र खाताहरूसम्म पुग्छ, र पैसा वास्तवमा कहाँ रेकर्ड हुन्छ।',
'Ord_Guide_Lifecycle_Title' => 'अर्डर स्थिति',
'Ord_Guide_Lifecycle_Pending' => 'तपाईंको समीक्षाको प्रतीक्षामा रहेको नयाँ अर्डर। विचाराधीन अर्डर मात्र पुष्टि वा रद्द गर्न सकिन्छ।',
'Ord_Guide_Lifecycle_Confirmed' => 'तपाईंले अर्डर स्वीकार गर्नुभयो। Stocky ले तपाईंले छानेको गोदाममा बिक्री सिर्जना गरी स्टक घटाउँछ — त्यही बिक्री तपाईंको स्टक, भुक्तानी र नाफा रिपोर्टहरूले पढ्ने रेकर्ड हो।',
'Ord_Guide_Lifecycle_Shipped' => 'तपाईंले अर्डर पठाउनुभयो। पूर्ति मात्र: पुष्टि गर्दा नै स्टक घटाइसकिएको थियो।',
'Ord_Guide_Lifecycle_Delivered' => 'ग्राहकले अर्डर प्राप्त गर्नुभयो। यसैबाट फिर्ता अवधि सुरु हुन्छ।',
'Ord_Guide_Lifecycle_Cancelled' => 'पुष्टि हुनुअघि नै अर्डर हटाइयो, त्यसैले कुनै बिक्री सिर्जना भएन र स्टक घटाइएन।',
'Ord_Guide_PaymentStatus_Tip' => 'चेकआउटमा सेट गरिन्छ र यहाँ सम्पादन गर्न मिल्दैन। भुक्तानी कसरी रेकर्ड गर्ने हेर्न क्लिक गर्नुहोस्।',
'Ord_Guide_Payment_Title' => 'भुक्तानी स्थिति',
'Ord_Guide_Payment_Intro' => 'यो स्तम्भले ग्राहकले चेकआउटमा कसरी भुक्तानी गर्ने छान्नुभयो भनी रेकर्ड गर्छ। यो स्टोरफ्रन्टले सेट गर्छ र यस पृष्ठबाट सम्पादन गर्न सकिँदैन — पैसा आफैं अर्डर पुष्टि गर्दा सिर्जना हुने बिक्रीमा ट्र्याक गरिन्छ।',
'Ord_Guide_Payment_Paid' => 'ग्राहकले भुक्तानी गेटवेमार्फत पहिले नै अनलाइन भुक्तानी गर्नुभएको छ। अर्डर पुष्टि गर्दा बिक्री भुक्तानी भएकोको रूपमा सिर्जना हुन्छ र तपाईंका लागि भुक्तानी रेकर्ड हुन्छ — अरू केही गर्नु पर्दैन।',
'Ord_Guide_Payment_Pending' => 'डेलिभरीमा नगद, बैंक ट्रान्सफर वा पछि भुक्तानी गर्ने अर्को विधि। अर्डर पुष्टि गर्दा बिक्री भुक्तानी नभएकोको रूपमा सिर्जना हुन्छ, त्यसैले पैसा सङ्कलन गरेपछि तपाईं आफैं रेकर्ड गर्नुहुन्छ — तलका चरणहरू हेर्नुहोस्।',
'Ord_Guide_Payment_Failed' => 'गेटवेले भुक्तानी अस्वीकार गर्‍यो वा ग्राहकले बीचमै छोड्नुभयो। अर्डर स्वतः रद्द हुन्छ।',
'Ord_Guide_MarkPaid_Title' => 'भुक्तानीलाई विचाराधीनबाट भुक्तानी भएकोमा परिवर्तन गर्दै',
'Ord_Guide_MarkPaid_Step1' => 'पहिले यहाँ अर्डर पुष्टि गर्नुहोस् — पुष्टि गर्नाले नै बिक्री सिर्जना हुन्छ।',
'Ord_Guide_MarkPaid_Step2' => 'बिक्री > सबै बिक्रीहरू खोलेर त्यो बिक्री फेला पार्नुहोस् (उही ग्राहक, र विवरण पृष्ठले यो आएको अनलाइन अर्डर देखाउँछ)।',
'Ord_Guide_MarkPaid_Step3' => 'पङ्क्तिको कार्य मेनु खोलेर भुक्तानी सिर्जना गर्नुहोस् छान्नुहोस्।',
'Ord_Guide_MarkPaid_Step4' => 'रकम, भुक्तानी विधि र मिति प्रविष्ट गरी सुरक्षित गर्नुहोस्। रकमअनुसार बिक्री आफैं आंशिक वा भुक्तानी भएकोमा सर्छ।',
'Ord_Guide_MarkPaid_Note' => 'यहाँ देखाइएको भुक्तानी स्थितिले चेकआउटको छनोट रेकर्ड गरिरहन्छ र जस्ताको तस्तै रहन्छ। बिक्री नै लेखा रेकर्ड हो, र त्यसैले तपाईंको भुक्तानी र नाफा रिपोर्टहरूलाई डाटा दिन्छ। तपाईंले प्रविष्ट गरेको कुरा समीक्षा वा सम्पादन गर्न बिक्रीमा भुक्तानीहरू देखाउनुहोस् प्रयोग गर्नुहोस्।',
'Ord_Guide_Notes_Title' => 'जान्नुपर्ने कुरा',
'Ord_Guide_Note_Warehouse' => 'पुष्टि गर्दा तपाईंले छान्ने गोदामले स्टक कहाँबाट लिने निर्धारण गर्छ। सम्पूर्ण अर्डर पूरा गर्न नसक्ने गोदामहरूलाई त्यो सूचीमा स्टक सकियो भनी चिन्ह लगाइन्छ।',
'Ord_Guide_Note_Preorder' => 'प्रि-अर्डर वस्तुहरूले स्टक जाँच छोड्छन्, त्यसैले ती समावेश भएको अर्डर परिमाण हातमा नहुँदा पनि पुष्टि गर्न सकिन्छ।',
'Ord_Guide_Note_Flagged' => 'चिन्ह लगाइएको ट्यागको अर्थ चेकआउटमा अर्डरले धोखाधडी जाँच ट्रिगर गर्‍यो। कारण हेर्न ट्यागमा होभर गर्नुहोस् र पुष्टि गर्नुअघि अर्डरको समीक्षा गर्नुहोस्।',
'Ord_Guide_Note_Cancel' => 'अर्डर विचाराधीन रहँदा मात्र रद्द गर्न सकिन्छ। पुष्टि भइसकेपछि, बिक्री वा ग्राहक फिर्तामार्फत उल्ट्याउनुहोस्।',
