'KitchenTargetMinutes' => 'तयारी लक्ष्य (मिनेट)',
'KitchenTargetMinutes_Help' => 'यो समयको आधा नाघेका टिकटहरू किचन डिस्प्लेमा पहेँलो हुन्छन्; पूरा समय नाघेपछि रातो हुन्छन्, झिम्किन्छन् र आफ्नो लेनको माथि पुग्छन्। असक्षम गर्न खाली छोड्नुहोस्।',
'KitchenAutoOnlineOrders' => 'पुष्टि भएका अनलाइन अर्डरहरू किचनमा स्वतः पठाउनुहोस्',
'KitchenAutoOnlineOrders_Help' => 'अनलाइन स्टोरको अर्डर पुष्टि हुँदा, त्यसका लागि किचन टिकट स्वतः सिर्जना हुन्छ।',
'KitchenStations' => 'किचन स्टेसनहरू',
