'StationCategoriesHint' => 'प्रत्येक स्टेसनले आफ्ना श्रेणीहरूका टिकट वस्तुहरू मात्र देखाउँछ। कुनै पनि स्टेसनले नलिएका श्रेणीका वस्तुहरू हरेक स्टेसनमा देखिन्छन्, त्यसैले केही पनि छुट्दैन। सबै स्टेसनहरू (expo) दृश्यले सधैं पूर्ण टिकटहरू देखाउँछ।',
