'Variants_Guide' => 'भेरियन्ट गाइड',
'VG_Intro' => 'परिवर्तनशील उत्पादन धेरै भेरियन्टहरूको रूपमा बेचिन्छ। तिनलाई विकल्पहरूबाट (सिफारिस गरिएको) वा नामहरूको सामान्य सूचीको रूपमा बनाउनुहोस्। हरेक भेरियन्टको आफ्नै कोड, मूल्य, तस्बिर र स्टक हुन्छ।',
'VG_Options_Title' => 'विकल्प मोड (रङ, साइज...)',
'VG_Opt_Step1' => 'कार्ड हेडरको स्विचलाई "विकल्पहरू" मा राख्नुहोस्।',
'VG_Opt_Step2' => 'रङ वा साइज जस्ता विकल्पको नाम टाइप गर्नुहोस्, वा सुझावहरूमध्ये एउटा छान्नुहोस्।',
'VG_Opt_Step3' => 'मान टाइप गर्नुहोस् (उदाहरणका लागि रातो) र Enter थिच्नुहोस्। प्रत्येक मानका लागि दोहोर्‍याउनुहोस्; अल्पविरामले पनि मानहरू छुट्याउँछ। मान हटाउन त्यसको x मा क्लिक गर्नुहोस्।',
'VG_Opt_Step4' => 'दोस्रो वा तेस्रो विकल्पका लागि "विकल्प थप्नुहोस्" मा क्लिक गर्नुहोस् (अधिकतम 3 विकल्पहरू)।',
'VG_Opt_Step5' => '"भेरियन्टहरू तयार गर्नुहोस्" मा क्लिक गर्नुहोस्। प्रत्येक संयोजनका लागि एउटा पङ्क्ति सिर्जना हुन्छ र यसको नाम स्वतः बनाइन्छ, उदाहरणका लागि "Red / S"।',
'VG_Opt_Step6' => 'प्रत्येक पङ्क्तिमा लागत र मूल्य प्रविष्ट गर्नुहोस्, वा "सबैमा लागू गर्नुहोस्" मा मान टाइप गरी हरेक पङ्क्तिमा प्रतिलिपि गर्न लागत वा मूल्यमा क्लिक गर्नुहोस्।',
'VG_Opt_Step7' => 'कोडहरू तपाईंका लागि तयार गरिन्छन्। आफ्नै टाइप गर्नुहोस् वा अर्को तयार गर्न रिफ्रेस आइकनमा क्लिक गर्नुहोस्।',
'VG_Opt_Step8' => 'वैकल्पिक: विकल्पमा "रङ स्वाचहरू" मा टिक लगाई प्रत्येक मानका लागि रङ छान्नुहोस्; स्टोरले यसलाई रङीन थोप्लाको रूपमा देखाउँछ।',
'VG_Rows_Title' => 'भेरियन्ट पङ्क्तिहरू',
'VG_Rows_Text' => 'प्रत्येक पङ्क्तिमा तस्बिर, कोड, बारकोड, लागत, मूल्य, थोक मूल्य र न्यूनतम बिक्री मूल्य हुन्छ। उत्पादन सिर्जना गर्दा तपाईं हरेक भेरियन्टका लागि प्रति गोदाम सुरुवाती स्टक पनि प्रविष्ट गर्न सक्नुहुन्छ। "अपूर्ण" ट्यागको अर्थ पङ्क्तिमा कुनै एक विकल्पको मान छैन।',
'VG_List_Title' => 'सामान्य सूची मोड',
'VG_List_Text' => 'पङ्क्ति थप्न भेरियन्टको नाम टाइप गरी Enter थिच्नुहोस् (वा थप्नुहोस् मा क्लिक गर्नुहोस्), त्यसपछि यसको कोड र मूल्यहरू भर्नुहोस्। यो पुरानो व्यवहार हो र अवस्थित उत्पादनहरूका लागि उपलब्ध रहन्छ।',
'VG_Edit_Title' => 'पछि सम्पादन गर्दा',
'VG_Edit_1' => 'मान थपेर "भेरियन्टहरू तयार गर्नुहोस्" मा क्लिक गर्नुहोस्: छुटेका संयोजनहरू मात्र थपिन्छन्। अवस्थित पङ्क्तिहरूले आफ्ना कोड, मूल्य र इतिहास कायम राख्छन्।',
'VG_Edit_2' => 'मान वा विकल्प हटाउँदा त्यसलाई प्रयोग गर्ने पङ्क्तिहरू हटाइन्छन्। पहिले नै सुरक्षित पङ्क्तिहरू पुष्टि गरेपछि उत्पादन सुरक्षित गर्दा मेटाइन्छन्।',
'VG_Edit_3' => 'अझै स्टक भएको भेरियन्ट हटाउन सकिँदैन। पहिले यसको स्टक समायोजन वा स्थानान्तरण गर्नुहोस्।',
'VG_Edit_4' => '"सामान्य सूची" मा बदल्दा पङ्क्तिहरू र तिनका नामहरू राखिन्छन् तर विकल्पका परिभाषाहरू हटाइन्छन्।',
'VG_Store_Title' => 'अनलाइन स्टोरमा',
'VG_Store_Text' => 'ग्राहकहरूले प्रत्येक विकल्पका लागि एउटा मान छान्छन्, उदाहरणका लागि रङ त्यसपछि साइज। अवस्थित नभएका संयोजनहरू असक्षम हुन्छन् र स्टक सकिएकाहरूमा धर्का लगाइन्छ। छानिएको भेरियन्ट नै कार्टमा जान्छ।',
'Choose_Source' => 'स्रोत छान्नुहोस्',
'Portal_Request' => 'पोर्टल अनुरोध',
'Portal_Quotation_Requests' => 'पोर्टल कोटेसन अनुरोधहरू',
'Warehouse_Invoice_Address_Help' => 'यो गोदामले जारी गरेका बिलहरूमा प्रिन्ट हुने सडक ठेगाना। सेटिङहरूको कम्पनी ठेगाना प्रयोग गर्न खाली छोड्नुहोस्।',
'Warehouse_Logo_Help' => 'यो गोदामका बिल र POS रसिदहरूमा प्रिन्ट हुने लोगो। कम्पनीको लोगो प्रयोग गर्न खाली छोड्नुहोस्।',
'Warehouse_Invoice_Footer_Help' => 'यो गोदामले जारी गरेका बिलहरूको तल प्रिन्ट हुने अतिरिक्त टिप्पणी।',
'Issued_By' => 'जारी गर्ने',
'Enable_Warehouse_Letterhead' => 'बिलहरूमा गोदामको लेटरहेड',
'Enable_Warehouse_Letterhead_Hint' => 'बिल, POS रसिद र सार्वजनिक बिल पृष्ठमा जारी गर्ने गोदाम प्रिन्ट गर्नुहोस्: यसको नामले कम्पनीको नामलाई प्रतिस्थापन गर्छ, र यसको ठेगाना, फोन, इमेल, लोगो र फुटर टिप्पणीले कम्पनीकालाई प्रतिस्थापन गर्छन्। गोदाममा खाली छोडिएको कुनै पनि फिल्डले विश्वव्यापी कम्पनी सेटिङहरू प्रयोग गर्छ।',
'Warehouse_Letterhead_Receipt_Notice' => 'गोदाम लेटरहेड अन छ: वास्तविक रसिदमा प्रिन्ट हुने स्टोरको नाम, ठेगाना र फोन बिक्री जारी गर्ने गोदामबाट आउँछन्, र यसको फुटर टिप्पणी ग्राहक टिप्पणीमुनि थपिन्छ।',
'Warehouse_Letterhead_Receipt_Demo' => 'शाखा फुटर टिप्पणी — गोदामहरूमा प्रति गोदाम सेट गर्नुहोस्।',
