'Upd_Note_Permission_Only' => 'टिप्पणी 2: एडमिन वा "{perm}" अनुमति भएको प्रयोगकर्ताले मात्र प्रणाली अपग्रेड गर्न सक्छ',
'Upd_Manual_Step_Backup_Db' => 'आफ्नो डेटाबेसको ब्याकअप लिनुहोस्। {backup} मा जानुहोस्, ब्याकअप उत्पन्न गर्नुहोस् मा क्लिक गर्नुहोस् — तपाईंले यसलाई {path} मा पाउनुहुनेछ — वा PhpMyAdmin बाट आफ्नो डेटाबेस निर्यात गरी आफ्नो PC मा सुरक्षित गर्नुहोस्।',
'Upd_Manual_Step_Backup_Files' => 'अपडेट गर्नुअघि आफ्ना फाइलहरूको ब्याकअप लिनुहोस्।',
