'Upd_Manual_Step_Clear_Cache' => 'आफ्नो ब्राउजर क्यास पूर्ण रूपमा खाली गर्नुहोस्।',
'Upd_Manual_Step_Done' => 'सम्पन्न भयो! अपडेट गरिएको एप्लिकेसनको आनन्द लिनुहोस्।',
'Upd_Note_Blank_Pages' => 'टिप्पणी: कुनै पृष्ठ लोड भएन वा खाली देखियो भने, आफ्नो ब्राउजर क्यास खाली गरेको सुनिश्चित गर्नुहोस्।',
'Upd_Guide_Before_Title' => '1. अपडेट गर्नुअघि',
'Upd_Guide_Before_Download' => 'आफ्नो CodeCanyon खाता ({path}) बाट एप्लिकेसनको {package} डाउनलोड गर्नुहोस्। यसलाई extract नगर्नुहोस् — अपडेटरलाई डाउनलोड गरिएकै ZIP चाहिन्छ।',
'Upd_Latest_Full_Zip' => 'नवीनतम पूर्ण ZIP प्याकेज',
'Upd_Guide_Before_Admin' => 'तपाईं {perm} अनुमति भएको प्रशासकको रूपमा लगइन हुनुहुन्छ भनी सुनिश्चित गर्नुहोस्। अरू कसैले अपडेटर हेर्न वा चलाउन सक्दैन।',
'Upd_Guide_Before_Quiet' => 'शान्त समय छान्नुहोस्: अपडेटको क्रममा एप्लिकेसन छोटो समयका लागि मर्मत मोडमा जान्छ र अन्य प्रयोगकर्ताहरू प्रवेश गर्न सक्दैनन्।',
'Upd_Guide_Before_No_Manual' => 'तपाईंले म्यानुअल रूपमा ब्याकअप लिन, फाइलहरू extract गर्न, कमान्डहरू चलाउन, कन्फिगरेसन फाइलहरू सम्पादन गर्न, वा डेटाबेस छुन आवश्यकता {not} — अपडेटरले ती सबै स्वचालित रूपमा गर्छ। (अतिरिक्त म्यानुअल ब्याकअपले भने कहिल्यै हानि गर्दैन।)',
'Upd_Not' => 'छैन',
'Upd_Guide_Code_Overwritten' => 'यदि तपाईंले एप्लिकेसनको कोड म्यानुअल रूपमा परिमार्जन गर्नुभएको छ भने, अपडेटले तपाईंका परिवर्तनहरू अधिलेखन गर्नेछ। तपाईंको डेटा, अपलोड, सेटिङ र .env सधैं सुरक्षित रहन्छन्।',
'Upd_Guide_Running_Title' => '2. अपडेट चलाउँदै',
'Upd_Guide_Run_Open' => '{path} (यो पृष्ठ) खोल्नुहोस् र {tab} ट्याबमै रहनुहोस्।',
'Upd_Guide_Run_Upload' => '{upload}: डाउनलोड गरिएको प्याकेजलाई अपलोड बाकसमा क्लिक वा ड्र्याग गर्नुहोस्। ठूला फाइलहरू साना टुक्राहरूमा अपलोड हुन्छन्, त्यसैले कम अपलोड सीमा भएको साझा होस्टिङमा पनि यो काम गर्छ। चेकसमले बिग्रिएका वा अपूर्ण अपलोडहरूबाट जोगाउँछ।',
'Upd_Upload_The_Zip' => 'ZIP अपलोड गर्नुहोस्',
'Upd_Guide_Run_Validation' => 'अपलोडपछि {auto} (तपाईं {button} बटनद्वारा यसलाई फेरि चलाउन सक्नुहुन्छ)। प्रणालीले जाँच गर्छ: ZIP अखण्डता, प्याकेज संरचना र पूर्णता, संस्करण अनुकूलता (डाउनग्रेड अस्वीकार गरिन्छ), आवश्यक PHP संस्करण र एक्सटेन्सनहरू, फाइल अनुमतिहरू, खाली डिस्क ठाउँ, डेटाबेस जडान, कन्फिगरेसन, र अर्को कुनै अपडेट चलिरहेको छैन भन्ने।',
'Upd_Validation_Runs_Automatically' => 'प्रमाणीकरण स्वचालित रूपमा चल्छ',
'Upd_Guide_Run_Review' => '{panel} प्यानल समीक्षा गर्नुहोस्। {button} बटन हरेक महत्त्वपूर्ण जाँच पास भएपछि मात्र देखिन्छ। कुनै जाँच असफल भएमा, सन्देशले के मिलाउनुपर्छ ठ्याक्कै बताउँछ।',
'Upd_Guide_Run_Click' => '{button} मा क्लिक गरी पुष्टि गर्नुहोस्। त्यसपछि केवल {keep} र प्रगति रेल हेर्नुहोस्। प्रणालीले क्रमशः यी गर्छ:',
'Upd_Keep_Page_Open' => 'यो पृष्ठ खुला राख्नुहोस्',
'Upd_Guide_Phase_Backup' => '{label} — पूर्ण डेटाबेस डम्प, अपडेटले परिवर्तन गर्न सक्ने हरेक एप्लिकेसन फाइलको ZIP, र {env} को प्रतिलिपि सिर्जना गरी {verified} गरिन्छ। तपाईंका अपलोड ({images}) र {storage} लाई अपडेटले कहिल्यै छुँदैन, त्यसैले तिनीहरू अभिलेखित हुँदैनन्। ब्याकअप सिर्जना गर्न सकिएन भने, अपडेट यहीँ रोकिन्छ र केही परिवर्तन हुँदैन।',
'Upd_Verified' => 'प्रमाणित',
'Upd_Guide_Phase_Prepare' => '{label} — नयाँ संस्करण स्टेजिङ क्षेत्रमा extract गरी फेरि प्रमाणित गरिन्छ। लाइभ एप्लिकेसन अझै अछुतो रहन्छ।',
'Upd_Guide_Phase_Maintenance' => '{label} — मर्मत मोड सक्रिय हुन्छ; आगन्तुकहरूले मैत्रीपूर्ण "हामी छिट्टै फर्कनेछौं" स्क्रिन देख्छन्।',
'Upd_Guide_Phase_Files' => '{label} — नयाँ फाइलहरू लगभग तुरुन्तै बदलिन्छन्; पुराना फाइलहरू रोलब्याकका लागि छुट्टै राखिन्छन्। सुरक्षित पथहरू ({env}, {storage}, {images}) कहिल्यै प्रतिस्थापन हुँदैनन्।',
'Upd_Guide_Phase_Database' => '{label} — माइग्रेसनहरू चल्छन्, त्यसपछि अनुमति, अनुवाद र टेम्प्लेटहरू ताजा गरिन्छन्।',
'Upd_Guide_Phase_Cache' => '{label} — सबै क्यासहरू खाली गरी पुनः निर्माण गरिन्छन्।',
'Upd_Guide_Phase_Verify' => '{label} — स्वास्थ्य जाँचहरूले नयाँ संस्करण सुरु हुन्छ, डेटाबेसले काम गर्छ, सबै माइग्रेसन चले, र कन्फिगरेसन मान्य छ भनी पुष्टि गर्छन्।',
'Upd_Guide_Phase_Done' => '{label} — मर्मत मोड हटाइन्छ र अस्थायी फाइलहरू सफा गरिन्छन्।',
'Upd_Guide_Run_Success' => '{success} देख्दा, {reload} मा क्लिक गर्नुहोस् र नयाँ एडमिन प्यानल एसेटहरू लोड होस् भनी आफ्नो ब्राउजर हार्ड-रिफ्रेस गर्नुहोस् ({keys})।',
'Upd_Update_Successful_Short' => 'अपडेट सफल भयो',
'Upd_Guide_No_Internet' => 'अपडेटको क्रममा इन्टरनेट जडान आवश्यक पर्दैन — सबै कुरा अपलोड गरिएको ZIP बाट आउँछ। जडान गुमाउँदा वा ब्राउजर बन्द गर्दा अपडेट बिग्रँदैन: सर्भरले ठ्याक्कै कहाँ रोकियो भन्ने सम्झन्छ।',
'Upd_Guide_Wrong_Title' => '3. केही गडबड भएमा',
'Upd_Guide_Wrong_Rollback' => '{label} — फाइलहरू परिवर्तन हुन थालेपछि केही असफल भएमा (extract त्रुटि, माइग्रेसन असफलता, स्वास्थ्य जाँच असफल, डिस्क भरिएको, …), प्रणालीले प्रमाणित ब्याकअपबाट अघिल्ला फाइलहरू र डेटाबेस स्वचालित रूपमा पुनर्स्थापना गर्छ, मर्मत मोड हटाउँछ, र {message} रिपोर्ट गर्छ। तपाईं ठ्याक्कै जहाँबाट सुरु गर्नुभएको थियो त्यहीँ पुग्नुहुन्छ।',
'Upd_Automatic_Rollback' => 'स्वचालित रोलब्याक',
'Upd_Failed_Previous_Restored' => 'अपडेट असफल भयो — अघिल्लो संस्करण पुनर्स्थापना गरियो',
'Upd_Guide_Wrong_Interrupted' => '{label} (सर्भर पुनः सुरु, टाइमआउट, ब्राउजर बन्द, बिजुली जाँदा) — तपाईंले यो पृष्ठ फेरि खोल्दा, रातो ब्यानरले दुई सुरक्षित विकल्प दिन्छ: {resume} (जहाँ रोकिएको थियो ठ्याक्कै त्यही चरणबाट जारी राख्छ) वा {rollback} (ब्याकअपबाट अघिल्लो संस्करण पुनर्स्थापना गर्छ)।',
'Upd_Interrupted_Update' => 'अवरुद्ध अपडेट',
'Upd_Guide_Wrong_Unreachable' => '{label} — {path} मा रहेको स्वतन्त्र {console} प्रयोग गर्नुहोस्। साइट मर्मत मोडमा हुँदा वा एडमिन प्यानल एसेटहरू बिग्रिएका बेला पनि यसले काम गर्छ, र उही जारी राख्ने / रोलब्याक कार्यहरू दिन्छ। मर्मत स्क्रिनको तल एउटा सानो "प्रशासक पहुँच" लिङ्क पनि छ।',
'Upd_Admin_Unreachable' => 'एडमिन प्यानलमा पहुँच छैन',
'Upd_Recovery_Console' => 'रिकभरी कन्सोल',
'Upd_Guide_Wrong_Locked_Out' => '{label} — अपडेट चलिरहँदा, यो पृष्ठले {link} देखाउँछ। फेरि भित्र पस्नुपर्ने भएमा (जस्तै तपाईंको सत्र सकिएपछि) यसलाई सुरक्षित राख्नुहोस्; यसले तपाईंलाई मर्मत स्क्रिन पार गराउँछ ताकि तपाईं फेरि लगइन गर्न सक्नुहुन्छ।',
'Upd_Locked_Out_Maintenance' => 'मर्मत मोडले बाहिर राखियो',
'Upd_Bypass_Link' => 'बाइपास लिङ्क',
'Upd_Guide_Wrong_Concurrent' => '{label} — उनीहरूले {message} देख्नेछन्। एक पटकमा एउटा मात्र अपडेट चल्न सक्छ।',
'Upd_Another_Admin_Updating' => 'अर्को एडमिनले एकै समयमा अपडेट गर्न खोज्छ',
'Upd_Guide_Backups_Title' => '4. ब्याकअप र पुनर्स्थापना',
'Upd_Guide_Backups_Created' => 'हरेक अपडेटले केही पनि छुनु {before} ब्याकअप बनाउँछ: अपडेटले प्रतिस्थापन गर्न सक्ने सबै एप्लिकेसन फाइलहरू, {env} को प्रतिलिपि, र पूर्ण डेटाबेस डम्प। अपलोड र {storage} लाई अपडेटले कहिल्यै परिमार्जन गर्दैन र त्यसैले ती यसको भाग होइनन् — तिनको आफ्नै ब्याकअप राख्नुहोस्। ब्याकअपहरू {path} मा रहन्छन् र वेबबाट कहिल्यै पहुँचयोग्य हुँदैनन्।',
'Upd_Before' => 'अघि',
'Upd_Guide_Backups_Panel' => '{tab} ट्याबको {panel} प्यानलले तिनीहरूलाई मिति, संस्करण र आकारसहित सूचीबद्ध गर्छ। त्यहाँबाट तपाईं कुनै पनि पूर्ण ब्याकअप {restore} सक्नुहुन्छ (फाइल + डेटाबेस — पहिले हालको डेटाबेसको सुरक्षा प्रतिलिपि लिइन्छ) वा पुराना {delete} सक्नुहुन्छ।',
'Upd_Restore_Verb' => 'पुनर्स्थापना गर्न',
'Upd_Delete_Verb' => 'मेटाउन',
'Upd_Guide_Backups_Retention' => 'कति ब्याकअपहरू राख्ने छान्न {keep} प्रयोग गर्नुहोस्; हरेक सफल अपडेटपछि पुराना स्वचालित रूपमा हटाइन्छन्। बाँकी रहेको एक मात्र पूर्ण ब्याकअप कहिल्यै मेटाउन सकिँदैन — तपाईंसँग सधैं फर्किने बाटो रहन्छ।',
'Upd_Guide_Manual_Title' => '5. म्यानुअल अपडेट (वैकल्पिक विधि)',
'Upd_Guide_Manual_Text' => 'यदि तपाईं हातैले अपडेट गर्न रुचाउनुहुन्छ, वा तपाईंको सर्भरमा अपलोडर प्रयोग गर्न सकिँदैन भने, यस पृष्ठको {tab} ट्याबमा रहेका चरणबद्ध निर्देशनहरू पालना गर्नुहोस्।',
'Upd_Guide_Clear_Cache_First' => 'कुनै पनि अपडेटपछि पृष्ठहरू बिग्रिएका वा खाली देखिए भने, पहिले आफ्नो ब्राउजर क्यास खाली गर्नुहोस् — प्रायः कारण यही हुन्छ।',
'Upd_Restore_Backup_Confirm' => 'यो ब्याकअप पुनर्स्थापना गर्ने? हालका फाइलहरू र हालको डेटाबेस ब्याकअपले प्रतिस्थापन हुनेछन्। पहिले हालको डेटाबेसको सुरक्षा प्रतिलिपि लिइन्छ। (v{version} — {date})',
'Woo_Guide_Lead' => 'WooCommerce पसलले आफूलाई ERP सँग कसरी मिलाइराख्छ। तलका cron लाइनहरू यही सर्भरका लागि बनाइएका छन्, त्यसैले तिनलाई सिधै यसमा कपी गर्न सकिन्छ।',
'Woo_Guide_Ways_Note' => 'Shopify जस्तो नभई, WooCommerce ले आफैं ERP मा केही पठाउँदैन — यहाँ कुनै webhook प्राप्तकर्ता छैन, त्यसैले {in} आउने सबै कुरा तालिका अनुसार आउँछ। {out} जाने स्टक मात्र तुरुन्तै जान सक्छ।',
'Woo_In' => 'भित्र',
'Woo_Out' => 'बाहिर',
'Woo_Guide_Both_Ways_Title' => 'दुवै दिशाका लागि पहिले यो चाहिन्छ',
'Woo_Api_Keys' => 'API कुञ्जीहरू',
'Woo_Guide_Api_Keys_Text' => '{path}, अनुमति {perm}। consumer key र secret लाई स्टोर URL सहित {settings} ट्याबमा कपी गर्नुहोस् — अन्त्यमा स्ल्यास बिनाको तपाईंको साइटको ठेगाना, जस्तै {example}।',
'Woo_Credentials_Saved' => 'क्रेडेन्सियल सुरक्षित गरियो',
'Woo_Not_Configured_Yet' => 'अझै कन्फिगर गरिएको छैन',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress एप्लिकेसन पासवर्ड (ऐच्छिक)',
'Woo_Guide_Wp_App_Password_Text' => 'उत्पादनका तस्बिरहरूका लागि मात्र प्रयोग गरिन्छ। WooCommerce API ले उत्पादन, स्टक, श्रेणी, ब्रान्ड, ग्राहक र अर्डरहरू सार्छ; WordPress API ले Media Library खोज्छ र त्यहाँ नभएको तस्बिर अपलोड गर्छ।',
'Woo_Guide_Wp_App_Password_Note' => 'मिडिया व्यवस्थापन गर्न सक्ने WordPress प्रयोगकर्ता प्रयोग गर्नुहोस्, र {path} अन्तर्गत पासवर्ड सिर्जना गर्नुहोस्। दुवै फिल्ड खाली छोड्दा पनि सबै कुरा सिङ्क हुन्छ — तस्बिर संलग्न गर्ने काम मात्र छोडिन्छ।',
'Woo_Guide_Pick_Way_Title' => 'त्यसपछि यो कसरी मिलिरहन्छ छान्नुहोस्',
'Woo_Right_Away' => 'तुरुन्तै',
'Woo_Stock_Live' => 'स्टक लाइभ',
'Woo_Stock_Not_Live' => 'स्टक लाइभ छैन',
'Woo_Guide_Realtime_Lead' => 'एउटा दिशा मात्र: ERP बाट बाहिर जाने स्टक र उत्पादनहरू। WooCommerce मा गरिएका अर्डर र उत्पादन सम्पादनहरू अझै तालिका अनुसार आउँछन् — अर्को ट्याब हेर्नुहोस्।',
'Woo_Push_Stock_On_Change' => 'स्टक परिवर्तन हुनासाथ पुश गर्नुहोस्',
'Woo_Setting_People_Miss' => 'मानिसहरूले छुटाउने सेटिङ यही हो',
'Woo_Guide_Pos_Sale_Not_Reach' => 'POS बिक्री आफैं WooCommerce मा {not}। बन्द छोडिएमा, पसलले अर्को स्टक सिङ्कमा मात्र थाहा पाउँछ — पूर्वनिर्धारित रूपमा एक घण्टा — र त्यो समयमा तपाईंले काउन्टरमा बेचिसकेको एकाइ यसले बेच्न सक्छ।',
'Woo_Does_Not' => 'पुग्दैन',
'Woo_Guide_Tick_Instant' => '{settings} ट्याबमा {option} मा टिक लगाउनुहोस्। पूरा सेटअप यत्ति हो — कुनै वर्कर छैन, कुनै cron छैन। त्यसपछि हरेक बिक्री, फिर्ता, समायोजन, स्थानान्तरण र प्राप्त खरिदले बिक्री सुरक्षित भएपछि तुरुन्तै ती उत्पादनहरूको मात्र पुश पठाउँछ, र बीस लाइनको बिक्रीले बीस होइन, एउटै पुश लिन्छ। काउन्टरले यसको प्रतीक्षा कहिल्यै गर्दैन।',
'Woo_Currently' => 'हाल:',
'Woo_Instant_On_Text' => 'चालू — परिवर्तनमा स्टक पुश हुन्छ',
'Woo_Instant_Off_Text' => 'बन्द — स्टक तालिका अनुसार मात्र',
'Woo_Guide_Instant_Note' => 'WooCommerce सँग पहिले नै जोडिएका उत्पादनहरू मात्र पुश हुन्छन् — कहिल्यै सिङ्क नभएको उत्पादनको पसलमा सच्याउनुपर्ने केही हुँदैन। भेरिएबल उत्पादनहरू तिनको मूल उत्पादनमार्फत जान्छन्, र कम्बोका कुनै पनि कम्पोनेन्ट सर्दा कम्बो फेरि पुश हुन्छ। बल्क कार्यहरू (उत्पादन मेटाउने, गोदाम रिसेट गर्ने) ले कुनै इभेन्ट नचलाई स्टक लेख्छन्, त्यसैले प्रति घण्टा स्टक सिङ्क पनि राख्नुपर्ने एउटा कारण यो हो।',
'Woo_Push_Products_On_Save' => 'उत्पादनहरू सुरक्षित हुनासाथ पुश गर्नुहोस्',
'Woo_Guide_Tick_Auto_Products' => '{settings} ट्याबमा {option} मा टिक लगाउनुहोस् र Stocky मा सिर्जना, सम्पादन वा दोहोर्याइएको उत्पादन सुरक्षित भएपछि तुरुन्तै WooCommerce मा पठाइन्छ — विवरण, मूल्य, भेरियन्ट र तस्बिरहरू, त्यसपछि यसको स्टक। नयाँ उत्पादन राती हुने उत्पादन सिङ्कको प्रतीक्षा नगरी पसलमा तुरुन्तै सिर्जना हुन्छ।',
'Woo_On' => 'चालू',
'Woo_Off' => 'बन्द',
'Woo_Guide_Bulk_Imports_Note' => 'बल्क आयातहरू एक-एक गरी पुश हुँदैनन् — आयातपछि उत्पादन सिङ्क चलाउनुहोस्। पुश गरिएको उत्पादन सही श्रेणीमा पुगोस् भनी पहिले श्रेणी र ब्रान्डहरू सिङ्क गर्नुहोस्।',
'Woo_Nothing_Else_To_Install' => 'अरू केही स्थापना गर्नुपर्दैन',
'Woo_Guide_Same_Process' => 'कुनै queue वर्कर छैन, कुनै cron प्रविष्टि छैन। पुश बिक्री सेवा दिने उही प्रक्रियामा, प्रतिक्रिया फर्किसकेको {after} चल्छ, त्यसैले काउन्टरले WooCommerce को प्रतीक्षा कहिल्यै गर्दैन। पुशहरू कहिल्यै ओभरल्याप हुँदैनन्: एउटा चलिरहँदा गरिएका परिवर्तनहरू त्यसको प्रतीक्षा गर्छन् र त्यसपछि तुरुन्तै जान्छन्।',
'Woo_After' => 'पछि',
'Woo_Guide_Shop_Stops_Answering' => 'जवाफ दिन छोडेको पसललाई आठ सेकेन्डपछि छोडिन्छ, र हरेक बिक्रीले फेरि यसको प्रतीक्षा नगरोस् भनी पुशहरू पाँच मिनेटका लागि रोकिन्छन्; बीचमा आएका परिवर्तनहरू रोकावटपछिको पहिलो पुशसँग जान्छन्, र प्रति घण्टा स्टक सिङ्कले जसरी पनि पूरा गर्छ। हरेक रोकावट लग ट्याबमा रेकर्ड हुन्छ।',
'Woo_Guide_Artisan_Exception' => 'एउटा अपवाद: artisan कमान्डले गरेको स्टक परिवर्तनको पछि आउने कुनै प्रतिक्रिया हुँदैन, त्यसैले यसलाई {queue} मा लाइनमा राखिन्छ। ती पनि तुरुन्तै जाऊन् भन्नका लागि, त्यो queue खाली गर्नुहोस्:',
'Woo_Cron_Line_Copied' => 'Cron लाइन कपी गरियो',
'Woo_Command_Copied' => 'कमान्ड कपी गरियो',
'Woo_Guide_Not_Woo_Queue' => 'जानाजानी {queue} queue होइन: त्यसले घण्टौं लामो क्याटलग ब्याचहरू बोक्छ, र त्यसको पछाडि लाइनमा राखिएको तुरुन्त पुश तुरुन्त हुने थिएन।',
'Woo_On_A_Schedule' => 'तालिका अनुसार',
'Woo_Guide_Scheduled_Lead' => 'सबै कुरा बेला-बेलामा दुवै दिशामा पुनः जाँच गरिन्छ। यसरी अर्डरहरू ERP मा पुग्छन्, क्याटलग प्रकाशित हुन्छ, र छिटो बाटोले छुटाएका कुराहरू मर्मत हुन्छन्। हरेक कामको आफ्नै cron प्रविष्टि हुन्छ, त्यसैले तपाईं चाहेको मात्र चलाउनुहुन्छ।',
'Woo_Guide_Sync_Drains_Queue' => '{command} ले चलिरहँदा आफ्नै queue खाली गर्छ, त्यसैले यी लाइनहरूलाई छुट्टै वर्कर चाहिँदैन। Windows मा, Task Scheduler मा प्रोग्राम {program} र उही आर्गुमेन्टहरू प्रयोग गर्नुहोस्, {path} मा सुरु गरिएको।',
'Woo_Or_No_Cron' => 'वा कुनै cron नै नराख्नुहोस्',
'Woo_Guide_No_Cron_Text' => 'यहाँका हरेक ट्याबले माग अनुसार सिङ्क गर्छ, र म्यानुअल सिङ्कले पृष्ठ खुला रहँदासम्म आफ्नै ब्याचहरू खाली गर्छ — त्यसैले सानो पसल कुनै cron प्रविष्टि बिना नै चल्न सक्छ। तपाईंले गुमाउने कुरा भनेको कसैले नहेरेको बेला हुने सबै कुरा हो: कसैले बटन थिचेपछि मात्र अर्डरहरू आउँछन्।',
'Woo_Commands_Worth_Knowing' => 'जान्न लायक कमान्डहरू',
'Woo_Worth_Knowing' => 'जान्न लायक',
'Woo_Guide_Changing_Url_Clears' => 'स्टोर URL वा API कुञ्जीहरू परिवर्तन गर्दा हरेक म्यापिङ खाली हुन्छ — उत्पादन, श्रेणी, ब्रान्ड र ग्राहकहरू सबै नयाँ स्टोरमा फेरि सिङ्क हुन्छन्।',
'Woo_Guide_Keep_Skus' => 'Stocky र WooCommerce बीच SKU हरू एकरूप राख्नुहोस्: यसैले दोहोरो हुनबाट रोक्छ र पुनः जोड्न सुरक्षित बनाउँछ।',
'Woo_Guide_Stock_Total' => 'Woo मा प्रकाशित स्टक {total} हो, एउटा गोदामको अंक होइन।',
'Woo_Total_Across_Warehouses' => 'सबै गोदामहरूको जम्मा',
'Woo_Guide_Full_Reference' => 'पूर्ण सन्दर्भ — हरेक दायरा, queue ले कसरी व्यवहार गर्छ, र समस्या समाधान सूची — {file} मा छ।',
'Woo_Way_Covers' => 'समेट्छ',
'Woo_Way_Covers_Realtime' => 'ERP बाट बाहिर जाने स्टक मात्र — POS बिक्री, फिर्ता, समायोजन, प्राप्त खरिद',
'Woo_Way_Covers_Scheduled' => 'सबै कुरा, दुवै दिशामा: अर्डर र उत्पादन परिवर्तनहरू भित्र, क्याटलग र स्टक बाहिर',
'Woo_Way_Speed' => 'गति',
'Woo_Way_Seconds' => 'सेकेन्डहरू',
'Woo_Way_Speed_Scheduled' => 'तपाईंले cron प्रविष्टिमा जे राख्नुहुन्छ (प्रति घण्टा स्टक, हरेक 15 मिनेटमा अर्डर)',
'Woo_Way_Needs' => 'आवश्यकता',
'Woo_Way_Needs_Realtime' => 'केही होइन — सेटिङ मात्र',
'Woo_Way_Needs_Scheduled' => 'प्रति काम एउटा cron प्रविष्टि — वा हातैले सिङ्क गर्नुहुन्छ भने केही पनि होइन',
'Woo_Way_Switched_On_At' => 'यहाँ सक्रिय गरिन्छ',
'Woo_Way_Cron_Entries_Below' => 'तलका cron प्रविष्टिहरू',
'Woo_Cron_Orders' => 'हरेक 15 मिनेटमा अर्डरहरू — पछिल्लो रनपछि परिवर्तन भएकाहरू मात्र।',
'Woo_Cron_Products_Pull' => 'पसलबाट उत्पादन परिवर्तनहरू, हरेक रात 03:00 मा।',
'Woo_Cron_Customers' => 'ग्राहकहरू, हरेक रात 03:30 मा।',
'Woo_Cron_Stock' => 'हरेक घण्टा स्टक — तुरुन्त पुशमुनिको सुरक्षा जाल, र त्यो बिना एक मात्र स्टक सिङ्क।',
'Woo_Cron_Products_Push' => 'अझै नजोडिएका उत्पादनहरू, हरेक रात 02:00 मा। विद्यमान उत्पादनहरू पुनः लेखिँदैनन्।',
'Woo_Cmd_Stock' => 'अहिले हरेक जोडिएको उत्पादनको स्टक पुश गर्नुहोस्।',
'Woo_Cmd_Products_Unsynced' => 'अझै WooCommerce id नभएका उत्पादनहरू प्रकाशित गर्नुहोस्।',
'Woo_Cmd_Orders' => 'पछिल्लो रनपछि परिवर्तन भएका अर्डरहरू आयात गर्नुहोस्।',
'Woo_Cmd_Orders_Full' => 'हालका परिवर्तनहरू मात्र नभई हरेक अर्डर पुनः स्क्यान गर्नुहोस्।',
'Woo_Cmd_Pull' => 'भित्र आउने सबै कुरा एकै पटक: उत्पादन, अर्डर, ग्राहक।',
'Woo_Guide_Page_Title' => 'WooCommerce गाइड',
'Woo_Guide_Page_Subtitle' => 'पसल जडान गर्ने, आफैं के चल्छ, र यो सर्भरका लागि cron प्रविष्टिहरू',
'Woo_Settings_Button' => 'WooCommerce सेटिङ',
'Woo_No_Shop_Connected' => 'अहिलेसम्म कुनै पसल जडान गरिएको छैन',
'Woo_No_Shop_Connected_Desc' => 'तलका सबै कुरा अझै लागू हुन्छन् — WooCommerce सेटिङ पृष्ठमा स्टोर URL र API कुञ्जीहरू प्रविष्ट गर्नुहोस्, अनि फर्कनुहोस्।',
'Woo_Wp_Username' => 'WordPress प्रयोगकर्ता नाम',
'Woo_Wp_App_Password' => 'WordPress एप्लिकेसन पासवर्ड',
'Woo_Settings_Instant_Hint' => 'बिक्री, फिर्ता वा समायोजन सुरक्षित हुनासाथ ती उत्पादनहरूको मात्र स्टक पुश पठाउँछ, त्यसैले पसल अर्को प्रति घण्टा स्टक सिङ्कमा होइन, सेकेन्डभित्रै सही हुन्छ। अरू केही स्थापना गर्नुपर्दैन — बिक्रीको जवाफ दिइसकेपछि पुश चल्छ, त्यसैले काउन्टरले WooCommerce को प्रतीक्षा कहिल्यै गर्दैन। थप जानकारी {guide} ट्याबमा।',
'Woo_Settings_Instant_Off_Alert' => 'बन्द छोड्दा POS बिक्री अर्को स्टक सिङ्कमा मात्र WooCommerce मा पुग्छ — एक घण्टासम्म पछि।',
'Woo_Settings_Auto_Products_Hint' => 'Stocky मा सिर्जना, सम्पादन वा दोहोर्याइएको उत्पादन सुरक्षित भएपछि तुरुन्तै WooCommerce मा पठाइन्छ — विवरण, मूल्य, भेरियन्ट, तस्बिर, त्यसपछि यसको स्टक — उत्पादन सिङ्कको प्रतीक्षा नगरी। बल्क आयातहरू पुश हुँदैनन्; आयातपछि उत्पादन सिङ्क चलाउनुहोस्।',
'Woo_Sync_Tuning' => 'सिङ्क ट्युनिङ',
'Woo_Sync_Tuning_Intro' => 'पूर्वनिर्धारितहरू धेरैजसो स्टोरहरूलाई उपयुक्त हुन्छन्। तपाईंको होस्टिङमा सिङ्क ढिलो भएमा वा टाइमआउट भएमा मात्र यिनलाई परिवर्तन गर्नुहोस्। हरेक मान सुरक्षित दायरामा सीमित हुन्छ, र फिल्ड खाली गर्दा यसको पूर्वनिर्धारित पुनर्स्थापित हुन्छ।',
'Woo_Setting_This_Up' => 'यसलाई सेटअप गर्दै',
'Woo_Setting_This_Up_Text' => 'API कुञ्जीहरू प्राप्त गर्ने, WordPress एप्लिकेसन पासवर्ड केका लागि हो, तालिकाबद्ध सिङ्कका लागि cron प्रविष्टिहरू, र स्टक परिवर्तन हुनासाथ पसलमा कसरी पुर्याउने — यी सबै, यो सर्भरकै cron लाइनहरू कपी गर्न तयार अवस्थामा, गाइड ट्याबमा छन्। एउटै प्रति, त्यसैले मोड्युलले वास्तवमा गर्ने कुराबाट यो फरक हुन सक्दैन।',
