'Telegram_G_Lead' => 'Stocky का सूचनाहरू Telegram च्याट, समूह वा च्यानलमा कसरी ल्याउने।',
'Telegram_G_Lead_Cron' => 'तलको cron लाइन यही सर्भरका लागि बनाइएको हो, त्यसैले यसलाई सिधै यसमा कपी गर्न सकिन्छ।',
