'Telegram_G_Step1_Title' => 'बट सिर्जना गर्नुहोस्',
'Telegram_G_Step1_Body' => 'Telegram मा {botfather} सँग च्याट खोल्नुहोस्, {cmd} पठाउनुहोस्, र बटका लागि नाम र प्रयोगकर्ता नाम छान्नुहोस्। BotFather ले {example} जस्तो {token} सहित जवाफ दिन्छ — त्यसलाई कपी गर्नुहोस्।',
'Telegram_G_Bot_Token_Inline' => 'बट टोकन',
'Telegram_G_Step2_Title' => 'Chat ID पत्ता लगाउनुहोस्',
'Telegram_G_Step2_Intro' => 'सन्देशहरू कहाँ जान्छन् भन्नेले तपाईंलाई कुन ID चाहिन्छ निर्धारण गर्छ:',
'Telegram_G_Own_Chat' => '{label} — पहिले आफ्नो नयाँ बटलाई कुनै सन्देश पठाउनुहोस् (बटले कुराकानी सुरु गर्न सक्दैन), अनि {bot} लाई सन्देश पठाउनुहोस्: यसले तपाईंको प्रयोगकर्ता ID जवाफमा दिन्छ।',
'Telegram_G_Your_Own_Chat' => 'तपाईंको आफ्नै च्याट',
'Telegram_G_Group' => '{label} — बटलाई समूहमा थप्नुहोस् र त्यसमा सन्देश पोस्ट गर्नुहोस्।',
'Telegram_G_A_Group' => 'एउटा समूह',
'Telegram_G_Channel' => '{label} — बटलाई च्यानलको {admin} को रूपमा थप्नुहोस् र त्यसमा सन्देश पोस्ट गर्नुहोस्।',
'Telegram_G_A_Channel' => 'एउटा च्यानल',
'Telegram_G_Administrator' => 'प्रशासक',
'Telegram_G_GetUpdates_Intro' => 'समूह वा च्यानलका लागि, यो ठेगाना आफ्नै टोकनसहित ब्राउजरमा खोल्नुहोस्, र पोस्ट गरेपछि रिफ्रेस गर्नुहोस्:',
'Telegram_G_Chat_Id_Note' => '{json} खोज्नुहोस्। समूह वा च्यानलको ID ऋणात्मक हुन्छ, जस्तै {example} — माइनस चिन्हसहित पूरै कपी गर्नुहोस्।',
'Telegram_G_Step3_Title' => 'यहाँ जडान गर्नुहोस्',
'Telegram_G_Step3_Body' => '{settings} ट्याबमा बट टोकन र chat ID टाँस्नुहोस्, {all} वा आफूलाई चाहिएका मात्र {events} छान्नुहोस्, {enable} सक्रिय गरी सुरक्षित गर्नुहोस्। त्यसपछि {test} थिच्नुहोस्।',
'Telegram_G_State_Enabled' => 'सक्रिय',
'Telegram_G_State_Off' => 'सुरक्षित गरियो, तर बन्द छ',
'Telegram_G_State_Not_Configured' => 'अझै कन्फिगर गरिएको छैन',
'Telegram_G_Chat_Label' => 'च्याट {id}',
'Telegram_G_How_Sent' => 'सन्देशहरू कसरी पठाइन्छन्',
'Telegram_G_A_Title' => 'तुरुन्तै — केही स्थापना गर्नुपर्दैन',
'Telegram_G_A_Body' => 'Stocky मा सुरक्षित गरिएको बिक्री, खरिद, भुक्तानी वा खर्च — POS मा वा एडमिनमा — सुरक्षित भएको {after} उही अनुरोधमा Telegram मा पठाइन्छ। कुनै cron प्रविष्टि छैन, कुनै queue वर्कर छैन, र क्यासियरले Telegram को प्रतीक्षा कहिल्यै गर्दैन: सन्देश जाँदा बिक्रीको जवाफ दिइसकिएको हुन्छ।',
'Telegram_G_Right_After' => 'तुरुन्तै पछि',
'Telegram_G_B_Title' => 'cron प्रविष्टि — पुनः प्रयास र पृष्ठभूमि घटनाहरूका लागि',
'Telegram_G_B_Body' => 'दुई प्रकारका सन्देशहरू भने Telegram को आफ्नै queue मा पर्खन्छन्: असफल भएको पठाइ (Telegram केही बेर पहुँचबाहिर हुँदा), जुन अर्को केही मिनेटमा थप तीन पटकसम्म पुनः प्रयास गरिन्छ; र एडमिनबाहिर उत्पन्न घटनाहरू — WooCommerce वा Shopify बाट आयात गरिएका अर्डरहरू, artisan कमान्डहरू। यो cron प्रविष्टिले तिनीहरू पठाउँछ, अरू केही होइन:',
'Telegram_G_Cron_Note' => 'हरेक मिनेट ठीक हो: केही नपर्खिरहेको रन तुरुन्तै बाहिरिन्छ। cPanel मा यो {cronJobs} मा जान्छ — {php} पुरानो भएमा PHP 8.2+ को पूरा पथ प्रयोग गर्नुहोस्। Windows मा, Task Scheduler मा प्रोग्राम {program}, आर्गुमेन्ट {args}, {path} मा सुरु गरिएको प्रयोग गर्नुहोस्।',
'Telegram_G_Waiting' => '{n} पठाउन बाँकी',
'Telegram_G_Nothing_Waiting' => 'केही बाँकी छैन',
'Telegram_G_Gave_Up' => '{n} पुनः प्रयासपछि छोडियो',
'Telegram_G_Growing_Note' => '— यो संख्या बढिरह्यो भने, cron प्रविष्टि चलिरहेको छैन।',
'Telegram_G_Without_Cron' => 'cron प्रविष्टि बिना पनि, Stocky मा सुरक्षित गरिएका सबै कुरा तुरुन्तै आउँछन्; तपाईंले पुनः प्रयास र आयात गरिएका अर्डरहरू मात्र गुमाउनुहुन्छ।',
'Telegram_G_Everything_Else' => 'अरू सबै',
'Telegram_G_Platform_Delivers' => 'पृष्ठभूमिमा उत्पन्न घटनाहरूका सन्देश प्लेटफर्मले पुर्याउँछ — सेटअप गर्नुपर्ने केही छैन।',
'Telegram_G_Not_Arrive' => 'यदि आइपुगेन भने',
'Telegram_G_Err_401' => '{error} — बट टोकन गलत छ। BotFather बाट फेरि टाँस्नुहोस्।',
'Telegram_G_Err_400' => '{error} — गलत chat ID, वा बट समूहमा छैन। व्यक्तिगत च्याटका लागि, पहिले बटलाई सन्देश पठाउनुहोस्।',
