'Salla_Guide_2' => 'एपको {clientId} र {clientSecret} लाई Connection ट्याबमा कपी गरी सुरक्षित गर्नुहोस्।',
'Salla_Guide_3' => 'एपको सेटिङमा, Connection ट्याबमा देखाइएको OAuth callback URL सेट गर्नुहोस्।',
'Salla_Guide_4' => 'एपको Webhooks पृष्ठमा: {signature} सुरक्षा रणनीति छान्नुहोस्, यसको secret यहाँको Webhook Secret फिल्डमा कपी गर्नुहोस्, Connection ट्याबमा देखाइएको Webhook URL सेट गर्नुहोस्, र कम्तीमा {e1}, {e2}, {e3}, {e4}, {e5} र {e6} मा सदस्यता लिनुहोस्।',
'Salla_Guide_5' => '{connect} मा क्लिक गरी आफ्नो स्टोरमा एप स्वीकृत गर्नुहोस्। (Easy Mode का एपहरू बरु {webhook} webhook मार्फत स्वचालित रूपमा जडान हुन्छन्।)',
'Salla_Guide_6' => 'उत्पादनहरू पुल वा पुश गर्नुहोस्, अनि स्टक पुश गर्नुहोस्। नयाँ अर्डरहरू स्वचालित रूपमा आउँछन् र {ref} जस्ता सन्दर्भसहित बिक्री अन्तर्गत देखिन्छन्।',
'Salla_Identity_Sku_Title' => 'उत्पादनको पहिचान SKU हो',
'Salla_Identity_Sku_Desc' => 'Stocky को उत्पादन कोड Salla को SKU सँग मिलाइन्छ। दुवैतिर SKU हरू एकरूप राख्नुहोस्; भेरियन्ट उत्पादनहरू पुल र अर्डरमा मिलाइन्छन्, तर यो संस्करणमा पुश हुँदैनन्।',
