'Presta_Not_Configured' => 'कन्फिगर गरिएको छैन',
'Presta_Hero_Desc' => 'उत्पादन, स्टक र अर्डरहरू आफ्नो PrestaShop स्टोरसँग यसको webservice API मार्फत सिङ्क गर्नुहोस्।',
'Presta_Webservice_Key' => 'Webservice कुञ्जी',
'Presta_Saved_Paste_New_Key' => 'सुरक्षित गरियो — प्रतिस्थापन गर्न नयाँ कुञ्जी टाँस्नुहोस्',
'Presta_From_Menu' => '{menu} बाट',
'Presta_Webservice_Key_Help' => 'PrestaShop ({menu}) मा webservice सक्रिय गर्नुहोस्, products, stock_availables, orders र customers मा अनुमतिसहित कुञ्जी सिर्जना गर्नुहोस्, र यहाँ टाँस्नुहोस्। लेख्न मात्र मिल्ने गरी भण्डारण गरिन्छ।',
'Presta_Shop_Language_Id' => 'पसलको भाषा ID',
'Presta_Shop_Language_Help' => 'पुश गर्दा उत्पादनका नामका लागि प्रयोग हुने भाषा id (1 = पसलको पहिलो भाषा)।',
'Presta_Push_Products_Desc' => 'PrestaShop मा नभएका साधारण उत्पादनहरू (तिनको हालको स्टकसहित) सिर्जना गर्छ। पहिले नै जोडिएका उत्पादन र भेरियन्ट उत्पादनहरू छोडिन्छन् — उत्पादन विवरणहरू PrestaShop मै सम्पादन गरिरहनुहोस्, वा स्थानीय प्रति ताजा गर्न पुल गर्नुहोस्।',
'Presta_Pull_Products_Desc' => 'PrestaShop उत्पादनहरू आयात गर्छ, विद्यमानहरूलाई reference (SKU) द्वारा मिलाउँछ र बाँकी सिर्जना गर्छ। Combinations लाई तिनको मूल उत्पादनको रूपमा आयात गरिन्छ।',
'Presta_Reset_Product_Confirm' => 'उत्पादन लिङ्कहरू रिसेट गर्ने? अर्डर इतिहासले आफ्ना लिङ्कहरू राख्छ।',
'Presta_Push_Stock_Desc' => 'हरेक जोडिएको उत्पादनका लागि पसलको स्टक (stock_availables) अपडेट गर्छ।',
'Presta_Pull_Orders_Desc' => 'पसलका अर्डरहरूलाई बिक्रीको रूपमा आयात गर्छ ({ref} जस्ता सन्दर्भ), नयाँ पहिले। पहिले नै आयात गरिएका र रद्द गरिएका अर्डरहरू छोडिन्छन्, त्यसैले नियमित पुल गर्नु सुरक्षित छ। PrestaShop मा webhook छैन — व्यस्त समयपछि यो चलाउनुहोस्।',
'Presta_Guide_1' => 'आफ्नो PrestaShop ब्याक अफिसमा, {menu} खोल्नुहोस् र webservice सक्रिय गर्नुहोस्।',
'Presta_Guide_2' => 'नयाँ कुञ्जी थप्नुहोस्, {products} र {stock} मा {rw}, र {orders} र {customers} मा {view} अनुमति दिँदै।',
'Presta_Guide_3' => 'Connection ट्याबमा स्टोर URL र कुञ्जी टाँस्नुहोस्, सुरक्षित गर्नुहोस्, र {test} चलाउनुहोस्।',
'Presta_Guide_4' => 'पसलमा पहिले नै क्याटलग छ भने पहिले उत्पादनहरू पुल गर्नुहोस् (reference/SKU द्वारा मिलाउँछ); नभएका साधारण उत्पादनहरू सिर्जना गर्न पुश गर्नुहोस्।',
'Presta_Guide_5' => 'परिमाण परिवर्तन हुँदा स्टक पुश गर्नुहोस्, र नियमित रूपमा अर्डरहरू पुल गर्नुहोस् — PrestaShop मा webhook छैन, त्यसैले तपाईंले पुल गर्दा मात्र अर्डरहरू आउँछन्।',
'Presta_Identity_Title' => 'उत्पादनको पहिचान reference (SKU) हो',
'Presta_Identity_Desc' => 'Stocky को उत्पादन कोड PrestaShop को reference सँग मिलाइन्छ। दुवैतिर reference हरू एकरूप राख्नुहोस्; combinations (भेरियन्टहरू) अर्डरमा reference द्वारा मिलाइन्छन् तर यो संस्करणमा पुश हुँदैनन्।',
'Xero_Hero_Title' => 'Xero लेखा सिङ्क',
'Xero_Hero_Desc' => 'आफ्ना ग्राहकहरूलाई Xero सम्पर्कको रूपमा र बिक्रीलाई इनभ्वाइसको रूपमा पुश गर्नुहोस् — बैंक खाता कन्फिगर गरिएको भए भुक्तानीसहित।',
'Xero_App_Credentials_Accounts' => 'एप क्रेडेन्सियल र खाताहरू',
