'Xero_Sales_Account_Code' => 'बिक्री खाता कोड',
'Xero_Sales_Account_Help' => 'इनभ्वाइस लाइनहरूका लागि आम्दानी खाता (\'200\' Xero को पूर्वनिर्धारित Sales खाता हो)।',
'Xero_Payment_Account_Code' => 'भुक्तानी खाता कोड (ऐच्छिक)',
'Xero_Payment_Account_Ph' => 'जस्तै 090',
'Xero_Payment_Account_Help' => 'बैंक खाता कोड। सेट गरिएमा, भुक्तानी भएका बिक्रीहरूले इनभ्वाइसमा भुक्तानी पनि रेकर्ड गर्छन्; इनभ्वाइस मात्र सिङ्क गर्न खाली छोड्नुहोस्।',
'Xero_Auto_Sync_Sales' => 'नयाँ बिक्रीहरूलाई इनभ्वाइसको रूपमा स्वतः सिङ्क गर्नुहोस्',
'Xero_Auto_Sync_Sales_Hint' => '(बिक्री सिर्जना हुँदै जाँदा पृष्ठभूमिमा queue मा राखिन्छ)',
