'Xero_Disconnect_Confirm' => 'Xero संस्था विच्छेद गर्ने? पुनः जडान नगरेसम्म सिङ्क रोकिन्छ।',
'Xero_Redirect_Uri_Title' => 'Xero एपका लागि Redirect URI',
'Xero_Redirect_Uri_Help' => '{link} मा "Web app" सिर्जना गर्नुहोस् र यो redirect URI दर्ता गर्नुहोस्। टिप्पणी: Xero access token हरू स्वतः रिफ्रेस हुन्छन्, तर 60 दिनभन्दा बढी निष्क्रिय रहेको जडान पुनः जडान गर्नुपर्छ।',
'Xero_Total_Customers' => 'कुल ग्राहकहरू',
'Xero_Contacts_In_Xero' => 'Xero मा सम्पर्कहरू',
'Xero_Total_Sales' => 'कुल बिक्री',
'Xero_Invoices_In_Xero' => 'Xero मा इनभ्वाइसहरू',
'Xero_Payments_Recorded' => 'रेकर्ड गरिएका भुक्तानीहरू',
'Xero_Push_Customers_To' => '{name} मा ग्राहकहरू पुश गर्नुहोस्',
'Xero_Push_Customers_Desc' => 'हरेक ग्राहकका लागि Xero सम्पर्क सिर्जना वा अपडेट गर्छ। Xero मा पहिले नै नाम भएको ग्राहक त्यो सम्पर्कसँग जोडिन्छ।',
'Xero_Push_Customers' => 'ग्राहकहरू पुश गर्नुहोस्',
'Xero_Push_Sales_Invoices' => 'बिक्रीलाई इनभ्वाइसको रूपमा पुश गर्नुहोस्',
'Xero_Push_Invoices_Desc' => 'प्रति बिक्री एउटा AUTHORISED इनभ्वाइस सिर्जना गर्छ (इनभ्वाइस नम्बर = बिक्रीको Ref), बिक्रीका लाइन सामानहरू साथै ढुवानी, छुट र कर लाइनहरूसहित ताकि Xero को जम्मा बिक्रीको जम्मासँग मिलोस्। Xero मा पहिले नै भएका बिक्रीहरू छोडिन्छन् — इनभ्वाइसहरू कहिल्यै सम्पादन गरिँदैनन्। नभएका सम्पर्कहरू तत्कालै सिर्जना गरिन्छन्।',
'Xero_Push_Invoices' => 'इनभ्वाइसहरू पुश गर्नुहोस्',
'Xero_Reset_Contact_Confirm' => 'सम्पर्क लिङ्कहरू रिसेट गर्ने? अर्को पुशले तिनलाई पुनः जोड्छ वा पुनः सिर्जना गर्छ।',
'Xero_Reset_Contact_Links' => 'सम्पर्क लिङ्कहरू रिसेट गर्नुहोस्',
'Xero_Guide_1' => '{link} ({menu}) मा {webApp} सिर्जना गर्नुहोस्।',
'Xero_Guide_2' => 'Connection ट्याबमा देखाइएको redirect URI दर्ता गर्नुहोस्।',
'Xero_Guide_3' => 'एपको {clientId} कपी गर्नुहोस् र {clientSecret} उत्पन्न गर्नुहोस्; दुवै यहाँ टाँसेर सुरक्षित गर्नुहोस्।',
'Xero_Guide_4' => '{connect} मा क्लिक गर्नुहोस्, साइन इन गर्नुहोस् र जडान गर्ने संस्था छान्नुहोस्।',
'Xero_Guide_5' => 'खाता कोडहरू जाँच गर्नुहोस्: बिक्री खाताले इनभ्वाइस लाइनहरू प्राप्त गर्छ; भुक्तानी भएका बिक्रीहरूले भुक्तानी पनि रेकर्ड गर्नुपर्छ भने बैंक खाता कोड सेट गर्नुहोस्।',
'Xero_Guide_6' => 'पहिले ग्राहकहरू पुश गर्नुहोस्, त्यसपछि इनभ्वाइसहरू। इनभ्वाइस नम्बरहरू बिक्रीका Ref हुन्, त्यसैले लिङ्कहरू रिसेट गरिए पनि Xero ले दोहोरोहरू अस्वीकार गर्छ।',
'Xero_Amounts_Title' => 'रकमहरू कर समावेश गरी जस्ताको तस्तै पुश गरिन्छ',
'Xero_Amounts_Desc' => 'इनभ्वाइसहरूले बिक्रीलाई ठ्याक्कै प्रतिबिम्बित गर्ने NoTax लाइनहरू प्रयोग गर्छन् (सामान + ढुवानी − छुट + कर), त्यसैले Xero को जम्मा सधैं Stocky को जम्मासँग बराबर हुन्छ। तपाईंको लेखापालले Xero भित्र कर र ढुवानी लाइनहरूलाई उपयुक्त खातामा पुनः म्याप गर्न सक्छन्।',
'Xero_Org_Connected' => 'Xero संस्था जडान भयो।',
'Jumia_Hero_Title' => 'Jumia मार्केटप्लेस सिङ्क',
'Jumia_Hero_Desc' => 'आफ्नो Jumia Seller Center सूचीहरूमा मूल्य र स्टक पुश गर्नुहोस् र मार्केटप्लेसका अर्डरहरूलाई बिक्रीको रूपमा आयात गर्नुहोस्।',
'Jumia_Api_Url_Label' => 'API URL (तपाईंको देशको Seller Center endpoint)',
'Jumia_Account_Email' => 'खाता इमेल (User ID)',
'Jumia_Api_Key' => 'API कुञ्जी',
'Jumia_Prices_Stock' => 'मूल्य र स्टक',
'Jumia_Push_Prices_Stock_Title' => 'Jumia मा मूल्य र स्टक पुश गर्नुहोस्',
'Jumia_Push_Prices_Stock_Desc' => 'Jumia सूचीको {sku} सँग मिल्ने SKU भएका हरेक उत्पादन (र भेरियन्ट) को हालको मूल्य र परिमाण पठाउँछ। अपडेटहरू Seller Center feed को रूपमा पेश गरिन्छन् र असिङ्क्रोनस रूपमा लागू हुन्छन् — feed ID लग ट्याबमा रेकर्ड हुन्छ, र प्रति सामान अस्वीकृतिहरू Seller Center को feed स्थिति स्क्रिनमा देखिन्छन्।',
'Jumia_Push_Prices_Stock' => 'मूल्य र स्टक पुश गर्नुहोस्',
'Jumia_Pull_Orders_Desc' => 'मार्केटप्लेसका अर्डरहरूलाई बिक्रीको रूपमा आयात गर्छ ({ref} जस्ता सन्दर्भ), Seller SKU द्वारा तपाईंका उत्पादनहरूसँग मिलाइन्छ। पहिले नै आयात गरिएका र रद्द गरिएका अर्डरहरू छोडिन्छन्, त्यसैले नियमित पुल गर्नु सुरक्षित छ। डेलिभर भएका अर्डरहरूका लागि मात्र भुक्तानी भएको चिन्ह लगाइन्छ (Jumia मा COD प्रमुख छ)।',
'Jumia_Guide_1' => 'Jumia {sellerCenter} मा, {menu} खोल्नुहोस् र API कुञ्जी उत्पन्न गर्नुहोस्।',
'Jumia_Guide_2' => 'आफ्नो देशको API URL (जस्तै नाइजेरियाका लागि {ng}, केन्याका लागि {ke}, इजिप्टका लागि {eg}), आफ्नो Seller Center खाता इमेल, र कुञ्जी प्रविष्ट गर्नुहोस् — अनि {test} चलाउनुहोस्।',
'Jumia_Guide_3' => 'हरेक Jumia सूचीको {sku} Stocky उत्पादन कोडसँग बराबर छ भनी सुनिश्चित गर्नुहोस् — स्टक पुश र अर्डर मिलान दुवैका लागि प्रयोग हुने पहिचान यही हो।',
'Jumia_Guide_4' => 'इन्भेन्टरी परिवर्तनपछि मूल्य र स्टक पुश गर्नुहोस्; नियमित रूपमा अर्डरहरू पुल गर्नुहोस् (यो API मा Jumia को webhook छैन)।',
'Jumia_Guide_5' => 'नयाँ सूचीहरू सिर्जना गर्ने काम Seller Center मै रहन्छ — Jumia ले श्रेणी-विशेष विशेषताहरू र तस्बिर समीक्षा माग्छ जुन उनीहरूको पोर्टलले मात्र राम्रोसँग सम्हाल्छ।',
'Mailchimp_Hero_Title' => 'Mailchimp दर्शक सिङ्क',
'Mailchimp_Hero_Desc' => 'Mailchimp दर्शकलाई आफ्ना ग्राहकहरूले भरिएको राख्नुहोस्, ताकि तपाईं आफ्नो वास्तविक ग्राहक आधारमा इमेल अभियानहरू चलाउन सक्नुहुन्छ।',
