'Mailchimp_Load_Audiences' => 'दर्शकहरू लोड गर्नुहोस्',
'Mailchimp_Double_Optin_Label' => 'डबल अप्ट-इन — नयाँ सदस्यहरूले सामेल हुनुअघि पुष्टि इमेल पाउँछन्',
'Mailchimp_Double_Optin_Hint' => '(GDPR का लागि सिफारिस गरिएको)',
'Mailchimp_Auto_Sync_Customers' => 'नयाँ ग्राहकहरू सिर्जना हुँदै जाँदा स्वतः सिङ्क गर्नुहोस्',
'Mailchimp_With_Email' => 'इमेल भएका',
'Mailchimp_Push_Desc' => 'इमेल ठेगाना भएका हरेक ग्राहकलाई छानिएको दर्शकमा upsert गर्छ (नाम र फोनसहित)। विद्यमान सदस्यहरूले आफ्नो सदस्यता स्थिति राख्छन् — सदस्यता हटाएका कसैलाई पनि पुनः सदस्य बनाइँदैन। इमेल नभएका ग्राहकहरू बाहिर राखिन्छन्।',
'Mailchimp_Double_Optin_Off_Title' => 'डबल अप्ट-इन बन्द छ',
'Mailchimp_Double_Optin_Off_Desc' => 'नयाँ सदस्यहरू पुष्टि इमेल बिना सदस्यको रूपमा थपिनेछन्। मार्केटिङ प्राप्त गर्न पहिले नै सहमत भएका ग्राहकहरूका लागि मात्र यो गर्नुहोस्।',
'Mailchimp_Guide_1' => 'Mailchimp मा, {menu} खोल्नुहोस् र कुञ्जी सिर्जना गर्नुहोस् (यो {suffix} मा अन्त्य हुन्छ — त्यो प्रत्यय तपाईंको datacenter हो)।',
'Mailchimp_Guide_2' => 'कुञ्जी यहाँ टाँस्नुहोस्, सुरक्षित गर्नुहोस्, अनि {load} मा क्लिक गरी भर्नुपर्ने दर्शक छान्नुहोस्।',
'Mailchimp_Guide_3' => 'तपाईंका ग्राहकहरूले मार्केटिङ इमेलका लागि पहिले नै सहमति नदिएसम्म {doubleOptIn} चालू राख्नुहोस्।',
'Mailchimp_Double_Optin_Term' => 'डबल अप्ट-इन',
'Mailchimp_Guide_4' => 'प्रारम्भिक भराइका लागि {push} चलाउनुहोस्; नयाँ ग्राहकहरू स्वचालित रूपमा सामेल होऊन् भनी {autoSync} सक्रिय गर्नुहोस्।',
'Mailchimp_Auto_Sync_Term' => 'स्वतः सिङ्क',
'Mailchimp_Consent_Title' => 'सहमति महत्त्वपूर्ण छ',
'Mailchimp_Consent_Desc' => 'मार्केटिङमा कहिल्यै सहमत नभएका मानिसहरूलाई इमेल गर्दा GDPR/CAN-SPAM उल्लङ्घन हुन सक्छ र तपाईंको Mailchimp खाता निलम्बन हुन सक्छ। डबल अप्ट-इनले पुष्टि Mailchimp मा सार्छ — सुरक्षित पूर्वनिर्धारित।',
