'Shopify_Hook_Msg_Token' => 'तलको “Register webhooks” मा क्लिक गर्नुहोस्, र एपको API secret key लाई स्टोर सेटिङमा signing secret को रूपमा टाँस्नुहोस्।',
'Shopify_Hook_Note_Register' => 'दर्ता गर्दा Shopify मा सदस्यताहरू सिर्जना हुन्छन् र तिनलाई स्वचालित रूपमा यो ठेगानामा निर्देशित गरिन्छ। यसलाई Shopify → Settings → Notifications → Webhooks अन्तर्गत हातैले नथप्नुहोस्: ती फरक secret ले हस्ताक्षरित हुन्छन् र हरेक डेलिभरी अस्वीकार हुनेछ।',
'Shopify_Hook_Verified_Client' => 'डेलिभरीहरू एपको client secret द्वारा प्रमाणित हुन्छन्, जुन पहिले नै भण्डारण गरिएको छ।',
'Shopify_Hook_Signature_Required' => 'मान्य हस्ताक्षर बिनाका डेलिभरीहरू अस्वीकार गरिन्छन्, त्यसैले webhook हरूले केही गर्नुअघि secret सेट गरिनुपर्छ।',
'Shopify_Hook_Retries' => 'Shopify ले 2xx नपाएसम्म पुनः प्रयास गर्छ, र हरेक डेलिभरी एक पटक मात्र रेकर्ड हुन्छ — दोहोरिएको घटनाले केही गर्दैन, दोहोरो अर्डर बन्दैन।',
