'Shopify_No_Signing_Secret_Desc' => 'यो बिना पनि सदस्यताहरू सिर्जना गर्न सकिन्छ, तर एपको API secret key यस स्टोरमा सुरक्षित नगरेसम्म हरेक डेलिभरी अस्वीकार हुनेछ (Dev Dashboard एपको client secret ले यो पहिले नै समेट्छ)।',
