'Shopify_G_Lead_Store' => 'यो पसललाई आफूलाई मिलाइराख्न के चाहिन्छ। यहाँका सबै कुरा यही स्टोरका लागि विशिष्ट छन् — पथ र id हरू वास्तविक हुन्, त्यसैले कमान्डहरू सिधै सर्भरमा कपी गर्न सकिन्छ।',
'Shopify_G_Lead_Generic' => 'Shopify पसलले आफूलाई ERP सँग कसरी मिलाइराख्छ। यसको आफ्नै स्थिति हेर्न माथि स्टोर छान्नुहोस्, वा जस्तो छ त्यस्तै पढ्नुहोस् — तपाईंले जुनसुकै स्टोर जडान गरे पनि cron लाइन र webhook URL उही हुन्छन्।',
'Shopify_G_Ways_Note' => 'धेरैजसो पसलहरूले दुवै चलाउँछन्: पहिलोले पसललाई मिनेट-मिनेटमा अद्यावधिक राख्छ, दोस्रोले पहिलोले छुटाएको कुरा समात्छ — कहिल्यै नआएको webhook, Shopify admin मा सिधै गरिएको सम्पादन, साइट बन्द भएको रात।',
'Shopify_G_Both_Need' => 'दुवै दिशाका लागि पहिले यो चाहिन्छ',
'Shopify_G_Credentials' => 'Shopify क्रेडेन्सियलहरू',
'Shopify_G_Cred_Intro' => 'जनवरी 2026 देखि Shopify ले admin भित्र custom एपहरू सिर्जना गर्दैन, त्यसैले दुई प्रकारका जडान छन्:',
'Shopify_G_Cred_DevDash' => '{app} (अहिले जडान गरिएको कुनै पनि पसल) — {path}। यो स्टोरले सिङ्क गर्ने कुराका लागि Admin API scopes दिनुहोस्, पसलमा एप स्थापना गर्नुहोस्, अनि एपको Settings पृष्ठबाट {clientId} र {clientSecret} लाई {where} मा कपी गर्नुहोस्। ERP ले तिनलाई आफैं access token मा साट्छ र हरेक 24 घण्टामा समाप्त हुनुअघि नवीकरण गर्छ। client secret ले webhook हरूमा पनि हस्ताक्षर गर्छ, त्यसैले अरू केही चाहिँदैन। एप र पसल एउटै Shopify संस्थामा हुनुपर्छ।',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard एप',
'Shopify_G_Cred_Legacy' => '{app} (2026 अघि admin मा सिर्जना गरिएको) — आफ्नो {token} ({prefix}) र webhook signing secret को रूपमा आफ्नो {secret} सहित परिवर्तन बिना काम गरिरहन्छ। यो टोकनजस्तै मान होइन, र तिनलाई उल्टो राख्नु नै webhook हरू अस्वीकार हुनुको सामान्य कारण हो।',
'Shopify_G_Legacy_App' => 'पुरानो custom एप',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'भण्डारण गरिएको',
'Shopify_G_Missing_Refused' => 'छैन — डेलिभरीहरू अस्वीकार हुनेछन्',
'Shopify_G_Where_Data_Desc' => '{path} यो पसलले बेच्ने स्टक भएको ERP गोदाम, र त्यो स्टक लेखिने Shopify स्थान। इन्भेन्टरी सिङ्क र अर्डर आयात दुवै यी बिना चल्न अस्वीकार गर्छन्।',
'Shopify_G_Currently' => 'हाल: गोदाम {warehouse}, स्थान {location}',
'Shopify_G_Not_Set_Lower' => 'सेट गरिएको छैन',
'Shopify_G_Ready' => 'तयार',
'Shopify_G_Incomplete' => 'अपूर्ण',
'Shopify_G_Manual_Syncs' => 'तपाईंले हातैले सुरु गर्ने सिङ्कहरू',
'Shopify_G_Manual_Desc' => '{centre} बाट सुरु गरिएको सिङ्कले तुरुन्तै जवाफ दिन्छ र पृष्ठभूमिमा छोटा टुक्राहरूमा चल्छ, प्रत्येक टुक्रा अघिल्लो रोकिएको ठाउँबाट जारी रहन्छ। लामा वेब अनुरोधहरू अन्त्य गर्ने होस्टिङ (LiteSpeed, nginx, load balancer) ले ठूलो क्याटलगलाई बीचमै कहिल्यै काट्दैन, र पृष्ठ बन्द गर्दा पनि यो रोकिँदैन। त्यसका लागि वर्कर एउटा थप cron लाइन हो:',
'Shopify_G_Cron_Copied' => 'Cron लाइन कपी गरियो',
'Shopify_G_Manual_Note' => 'यो बिना पनि सिङ्क पूरा हुन्छ, तर Sync Centre पृष्ठ खुला रहँदासम्म मात्र: केही सेकेन्डभित्र कुनै वर्करले रन नउठाएमा, पृष्ठले आफैं यसलाई एक-एक छोटो अनुरोध गर्दै जारी राख्छ। Windows मा हरेक मिनेट Task Scheduler प्रयोग गर्नुहोस्: प्रोग्राम {program}, आर्गुमेन्ट {args}, {dir} मा सुरु गरिएको।',
'Shopify_G_Then_Pick' => 'त्यसपछि यो कसरी मिलिरहन्छ छान्नुहोस्',
'Shopify_G_Right_Away' => 'तुरुन्तै',
'Shopify_G_Stock_Live' => 'स्टक लाइभ',
'Shopify_G_Stock_Not_Live' => 'स्टक लाइभ छैन',
'Shopify_G_Realtime_Lead' => 'हरेक परिवर्तन हुनासाथ सेकेन्डमै पठाइन्छ। दुई भाग, र ती छुट्टाछुट्टै स्विच हुन्: {webhooks} ले पसलका आफ्नै घटनाहरू भित्र ल्याउँछन्, र {push} ले स्टक बाहिर पठाउँछ।',
'Shopify_G_Webhooks_Lower' => 'webhook हरू',
'Shopify_G_Instant_Push_Lower' => 'तुरुन्त स्टक पुश',
'Shopify_G_Webhooks_In' => 'Webhooks — पसल → ERP',
'Shopify_G_Webhooks_Desc' => 'अर्डर, अर्डर स्थिति परिवर्तन, र Shopify मा गरिएका उत्पादन, ग्राहक र स्टक सम्पादनहरू। स्टोर खोल्नुहोस् र यसको {tab} मा {button} थिच्नुहोस् — दुई पटक थिच्नु सुरक्षित छ। Shopify ले यहाँ पोस्ट गर्छ:',
'Shopify_G_Webhooks_Tab' => 'Webhooks ट्याब',
'Shopify_G_Webhooks_Note' => 'ठेगाना इन्टरनेटबाट HTTPS मार्फत पहुँचयोग्य हुनुपर्छ — Shopify ले {localhost} वा {test} डोमेनमा डेलिभर गर्दैन। हरेक डेलिभरी एक पटक मात्र रेकर्ड हुन्छ, त्यसैले Shopify का पुनः प्रयासहरूले दोहोरो अर्डर बनाउन सक्दैनन्, र असफल भएकोलाई पुनः चलाउन सकिन्छ। चरण 1 को signing secret भण्डारण नभएसम्म डेलिभरीहरू अस्वीकार गरिन्छन्।',
'Shopify_G_Instant_Out' => 'तुरुन्त स्टक पुश — ERP → पसल',
'Shopify_G_Setting_Missed' => 'मानिसहरूले छुटाउने सेटिङ यही हो',
'Shopify_G_Pos_Not_Auto' => 'POS बिक्री आफैं Shopify मा पुग्ने {not}। बन्द छोडिएमा, पसलले अर्को Inventory पुश चरणमा मात्र थाहा पाउँछ — र त्यो समयमा तपाईंले काउन्टरमा बेचिसकेको एकाइ यसले बेच्न सक्छ।',
'Shopify_G_Not' => 'छैन',
'Shopify_G_Tick_Push' => '{where} मा {setting} मा टिक लगाउनुहोस्। पूरा सेटअप यत्ति हो — कुनै वर्कर छैन, कुनै cron छैन। त्यसपछि हरेक बिक्री, फिर्ता र समायोजनले बिक्री सुरक्षित भएपछि तुरुन्तै ती उत्पादनहरूको मात्र पुश पठाउँछ, र बीस लाइनको बिक्रीले बीस होइन, एउटै पुश लिन्छ। काउन्टरले यसको प्रतीक्षा कहिल्यै गर्दैन।',
'Shopify_G_This_Store' => 'यो स्टोर:',
'Shopify_G_Push_On' => 'चालू — परिवर्तनमा स्टक पुश हुन्छ',
'Shopify_G_Push_Off' => 'बन्द — स्टक तालिका अनुसार मात्र',
'Shopify_G_Push_Note' => 'पहिले नै Shopify म्यापिङ भएका उत्पादनहरू, र यो स्टोरको गोदामका आवागमनहरू मात्र पुश हुन्छन्। बल्क कार्यहरू — उत्पादन मेटाउने, गोदाम रिसेट गर्ने — ले कुनै इभेन्ट नचलाई स्टक लेख्छन्, त्यसैले तालिकाबद्ध इन्भेन्टरी चरण पनि राख्नुपर्ने एउटा कारण यो हो।',
'Shopify_G_Nothing_Install' => 'अरू केही स्थापना गर्नुपर्दैन',
'Shopify_G_No_Worker_Note' => 'कुनै पनि भागलाई queue वर्कर वा cron प्रविष्टि चाहिँदैन। भित्र आउने webhook लाई Shopify ले गर्ने अनुरोधमै सम्हालिन्छ; बाहिर जाने स्टक पुश बिक्री सेवा दिने उही प्रक्रियामा, प्रतिक्रिया फर्किसकेको {after} चल्छ — त्यसैले काउन्टरले Shopify को प्रतीक्षा कहिल्यै गर्दैन, र जवाफ दिन छोडेको पसललाई दस सेकेन्डपछि छोडिन्छ र अर्को तालिकाबद्ध इन्भेन्टरी पुशमा छाडिन्छ।',
'Shopify_G_After' => 'पछि',
'Shopify_G_Artisan_Note' => 'एउटा अपवाद: artisan कमान्डले गरेको स्टक परिवर्तनको पछि आउने कुनै प्रतिक्रिया हुँदैन, त्यसैले यसलाई {queue} मा लाइनमा राखिन्छ। ती पनि तुरुन्तै जाऊन् भन्ने चाहनुहुन्छ भने, त्यो queue खाली गर्नुहोस्:',
'Shopify_G_On_Schedule' => 'तालिका अनुसार',
'Shopify_G_On_Lower' => 'चालू',
'Shopify_G_Off_Lower' => 'बन्द',
'Shopify_G_Scheduled_Lead' => 'सबै कुरा बेला-बेलामा दुवै दिशामा पुनः जाँच गरिन्छ। वास्तविक समयभन्दा ढिलो, तर तुरुन्त पुश प्रयोग नगर्ने पसलहरूमा स्टक बाहिर पठाउने, छुटेको webhook समात्ने, र सम्पूर्ण क्याटलग सार्ने एक मात्र तरिका यही हो।',
'Shopify_G_Cron_Entry' => 'cron प्रविष्टि',
'Shopify_G_Cron_Entry_Desc' => 'यो बिना कुनै तालिकाबद्ध काम चल्दैन। एउटा लाइन, यो मोड्युलका लागि मात्र — तपाईंले तालिकाबद्ध गर्न छानेका अरू कुराहरूको छेउमा थप्नुहोस्:',
'Shopify_G_Cron_Note' => 'हरेक पाँच मिनेट योजनाले प्रयोग गर्न सक्ने सबैभन्दा सूक्ष्म रिजोल्युसन हो, किनभने पाँच मिनेट सबैभन्दा छोटो चरण अन्तराल हो। अझ मोटो प्रविष्टि केवल न्यूनतम सीमा बन्छ — {example} सहित, 5 मिनेटमा सेट गरिएको चरण हरेक 15 मा चल्छ। Windows मा Task Scheduler प्रयोग गर्नुहोस्: प्रोग्राम {program}, आर्गुमेन्ट {args}, {dir} मा सुरु गरिएको।',
'Shopify_G_Switch_On_Plan' => 'यसलाई सक्रिय गर्नुहोस्, र योजना छान्नुहोस्',
'Shopify_G_Plan_Desc' => '{where} स्विचले cron ले काम गर्न पाउँछ कि पाउँदैन निर्णय गर्छ; योजनाले यसले के गर्छ निर्णय गर्छ। {step} भनेको आफ्नै अन्तरालसहित एउटा दिशामा एउटा इकाइ हो — {first}, {second}। आफ्नो बाकस खाली छोड्ने कुनै पनि चरणले पूर्वनिर्धारित अन्तराल प्रयोग गर्छ।',
'Shopify_G_Step_Lower' => 'चरण',
'Shopify_G_Plan_Note' => 'योजना खाली छोड्नुहोस् र स्टोरले पूर्वनिर्धारित अन्तरालमा अर्डरहरू पुल गर्छ र स्टक पुश गर्छ, जुन धेरैजसो पसलहरूले चाहन्छन्। अर्डरहरू पुल मात्र हुन्छन्: ग्राहकले अर्डर Shopify मै राख्छन्।',
'Shopify_G_Schedule_On' => 'तालिका चालू',
'Shopify_G_Schedule_Off' => 'तालिका बन्द — म्यानुअल मात्र',
'Shopify_G_When_Step_Runs' => 'चरण वास्तवमा कहिले चल्छ',
'Shopify_G_When_Note' => 'रन इतिहासबाट पढिए अनुसार, त्यही चरण अन्तिम पटक यसको अन्तरालभन्दा पहिले {started} भए चरण गर्नुपर्ने हुन्छ। त्यसैले तपाईंले हातैले सुरु गरेको सिङ्कले अर्को स्वचालितलाई पछाडि धकेल्छ, र बारम्बार असफल हुने चरण हरेक टिकमा होइन, आफ्नो अन्तरालमा पुनः प्रयास गरिन्छ। स्टोरको Overview ले हरेक चरणको अन्तिम रन, अर्को गर्नुपर्ने समय, र रोकिएको भए त्यसको कारण देखाउँछ। पहिलो क्याटलग पुश तालिकामा राख्नुअघि हातैले चलाउनुहोस् — पहिले {dryRun} सहित।',
'Shopify_G_Started_Lower' => 'सुरु भएको',
'Shopify_G_Where_Setting' => 'हरेक सेटिङ कहाँ छ',
'Shopify_G_Where_Setting_Note' => 'यी सबै विद्यमान स्टोरमा छन्: {path}, अनि पेन्सिल (वा स्टोरको आफ्नै पृष्ठमा {edit})।',
'Shopify_G_Product_Images' => 'उत्पादनका तस्बिरहरू',
'Shopify_G_Img_1' => 'तस्बिरहरू {push} मा उत्पादनसँगै जान्छन् — पहिले मुख्य तस्बिर, त्यसपछि ग्यालरी, त्यसपछि आफ्नै तस्बिर भएका प्रत्येक भेरियन्टको एउटा, पचाससम्म।',
'Shopify_G_Products_Push' => 'उत्पादन पुश',
'Shopify_G_Img_2' => 'भेरियन्टको तस्बिर उत्पादनसँग अपलोड गरिन्छ र त्यसपछि {assigned}, Shopify ले यसलाई यसरी नै मोडेल गर्छ: भेरियन्टले उत्पादनका तस्बिरहरूमध्ये एउटालाई देखाउँछ। मुख्य तस्बिर पुनः प्रयोग गर्ने भेरियन्टले त्यसलाई दुई पटक अपलोड गर्दैन।',
'Shopify_G_Assigned' => 'त्यो भेरियन्टमा तोकिन्छ',
'Shopify_G_Img_3' => 'फाइलको रूपमा भण्डारण गरिएको तस्बिर Shopify मा {uploaded}, लिङ्क गरिँदैन, त्यसैले यो इन्स्टलेसन इन्टरनेटबाट पहुँचयोग्य नभए पनि काम गर्छ। टाँसिएको लिङ्कको रूपमा थपिएको तस्बिर Shopify लाई त्यही URL को रूपमा दिइन्छ, जुन सार्वजनिक रूपमा पहुँचयोग्य हुनुपर्छ।',
'Shopify_G_Uploaded' => 'अपलोड गरिन्छ',
'Shopify_G_Img_4' => 'तिनीहरू वास्तवमा परिवर्तन हुँदा मात्र पुनः पठाइन्छन् — मूल्य मात्र परिवर्तन गर्ने पुशले पसलका तस्बिरहरूलाई छुँदैन, किनभने तिनलाई पठाउँदा पूरै सेट प्रतिस्थापन हुन्छ।',
'Shopify_G_Img_5' => 'ERP मा तस्बिर हटाउँदा Shopify मा मेटिने {not}। त्यहाँ पनि मेटाउनुहोस्, नत्र पसलले त्यसलाई देखाइरहन्छ।',
'Shopify_G_Commands' => 'जान्न लायक कमान्डहरू',
'Shopify_G_Command_Copied' => 'कमान्ड कपी गरियो',
'Shopify_G_Foot' => 'हरेक सिङ्कले {logs} मा लेख्छ, र प्रत्येक स्टोरको Overview ले हरेक चरण अन्तिम पटक कहिले चल्यो, अर्को कहिले गर्नुपर्ने छ, र केही रोकिएको भए के ले रोकिरहेको छ देखाउँछ। सिङ्कले तपाईंले अपेक्षा गरेको काम नगरेमा पहिले हेर्ने ठाउँ यही हो।',
'Shopify_G_Covers' => 'समेट्छ',
'Shopify_G_Covers_Rt' => 'Shopify मा गरिएका अर्डर र सम्पादनहरू; ERP बाट बाहिर जाने स्टक (POS बिक्री, फिर्ता, समायोजन)',
'Shopify_G_Covers_Sch' => 'सबै कुरा, दुवै दिशामा — क्याटलग पुश र छिटो बाटोले छुटाएका कुराहरूसहित',
'Shopify_G_Speed' => 'गति',
'Shopify_G_Speed_Rt' => 'सेकेन्डहरू',
'Shopify_G_Speed_Sch' => 'चरणको अन्तराल (5 मिनेटदेखि 7 दिनसम्म)',
'Shopify_G_Needs' => 'आवश्यकता',
'Shopify_G_Needs_Rt' => 'सार्वजनिक HTTPS ठेगाना र भित्र आउने webhook हरूका लागि signing secret। बाहिर जाने स्टकलाई केही पनि चाहिँदैन',
'Shopify_G_Needs_Sch' => '{cmd} चलाउने cron प्रविष्टि',
'Shopify_G_Switched_On_At' => 'यहाँ सक्रिय गरिन्छ',
