'Shopify_G_Set_Create_Missing_What' => 'पुलले मिलाउन नसकेका ERP रेकर्डहरू सिर्जना गर्न पाउँछ कि पाउँदैन।',
'Shopify_G_Set_Entities' => 'कुन इकाइहरू सिङ्क हुन्छन्',
'Shopify_G_Set_Entities_What' => 'यहाँ बन्द भनेको सबैतिर बन्द — म्यानुअल, तालिकाबद्ध र webhook।',
'Shopify_G_Set_Scheduler_What' => 'तालिका स्विच।',
'Shopify_G_Set_Push_What' => 'तुरुन्त स्टक पुश, बिक्री वा समायोजनमा लाइनमा राखिन्छ।',
'Shopify_G_Set_Plan' => 'पूर्वनिर्धारित अन्तराल, र चरणहरूको योजना',
