'StoreAdm_Eg' => 'जस्तै {example}',
'StoreAdm_Stock_Required_Available' => '{name}: आवश्यक {need} — उपलब्ध {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash र SSLCommerz अनलाइन स्टोर चेकआउटमा मात्र प्रयोग हुन्छन्।',
'StoreAdm_PG_Intro_Desc' => 'Stripe कुञ्जीहरू विश्वव्यापी रूपमा साझा हुन्छन् (एडमिन र अनलाइन स्टोरले उही Stripe एकीकरण प्रयोग गर्छन्)। प्रत्येक ट्याबले अनलाइन स्टोर चेकआउटका लागि आफ्नो विधि सक्रिय वा निष्क्रिय गर्छ; अफलाइन भुक्तानीले प्रणालीबाहिर तिरिने विधिहरू राख्छ।',
'StoreAdm_PG_Used_By_Store_Only' => 'अनलाइन स्टोर चेकआउटले मात्र प्रयोग गर्छ',
