'StoreAdm_PG_Gw_Secret' => '{gw} Secret',
'StoreAdm_PG_Cards_Off' => 'कार्ड भुक्तानी बन्द छ',
'StoreAdm_PG_Cards_Off_Desc' => 'तपाईंका कुञ्जीहरू राखिन्छन् — तपाईंले फेरि सक्रिय नगरेसम्म अनलाइन स्टोर चेकआउटले कार्ड विकल्प दिन मात्र छोड्छ।',
'StoreAdm_PG_No_Stripe_Key' => 'कुनै Stripe कुञ्जी भण्डारण गरिएको छैन',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'अनलाइन स्टोरमा कार्ड भुक्तानी स्वीकार गर्न सुरु गर्न आफ्नो Stripe key र secret प्रविष्ट गर्नुहोस्।',
